insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('after-hours-work-email-boundary-sheet', 'After-Hours Work Email Boundary Sheet', 'worksheet'::resource_kind, 'A sheet for deciding when work email is closed for the day, what counts as a true exception, and what to do with the itch to check.', 'Use it to help a client whose evenings are eaten by the inbox draw a line they can actually hold.', array['Adults']::text[], '20 minutes to plan, two weeks to use', 'Most clients who say they cannot stop checking have never decided when checking ends. The sheet asks for a closing time, a short list of what would truly justify opening the inbox after it, where the phone lives in the evening, and a replacement for the first ten minutes after closing. Review the exceptions list closely; it tends to grow until it covers everything. Watch for a client who treats a manager''s late message as an order to reply tonight, and ask what the message actually said about timing.', '[{"id": "f0", "type": "textarea", "label": "The time my work email closes on a normal weekday, and on a weekend:"}, {"id": "f1", "type": "textarea", "label": "The two or three things that would genuinely justify opening it after that time:"}, {"id": "f2", "type": "textarea", "label": "Where my phone or laptop will be during the evening so checking takes effort:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the first ten minutes after closing, when the itch is strongest:"}, {"id": "f4", "type": "textarea", "label": "Evenings this week I held the line, and evenings I did not, with what pulled me in:"}, {"id": "f5", "type": "textarea", "label": "What happened at work because I waited until morning:"}]'::jsonb, array['boundaries', 'stress', 'routines']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('recurring-commitments-audit-sheet', 'Recurring Commitments Audit Sheet', 'worksheet'::resource_kind, 'An audit of every standing commitment, from committees to group chats, with what each costs, what it gives, and whether it stays.', 'Use it to help an overcommitted client see the whole load at once and choose what to put down.', array['Adults']::text[], '40 minutes', 'Ask the client to list every recurring commitment they have said yes to: volunteer roles, standing calls, clubs, carpools, the group chat they feel obliged to answer. For each, they note the hours a month, what it gives them, and who would be affected if they stepped back. Then they sort into keep, shrink and release. Watch for commitments kept out of guilt alone, and for the client who releases nothing because every item feels non-negotiable; ask which one they would drop if a doctor ordered it.', '[{"id": "f0", "type": "textarea", "label": "Every recurring commitment I currently have, large and small:"}, {"id": "f1", "type": "textarea", "label": "For each one: roughly how many hours a month it takes:"}, {"id": "f2", "type": "textarea", "label": "For each one: what it actually gives me, if anything:"}, {"id": "f3", "type": "textarea", "label": "Who would be affected if I stepped back from each, and how much:"}, {"id": "f4", "type": "textarea", "label": "My keep, shrink and release lists:"}, {"id": "f5", "type": "textarea", "label": "The one I will shrink or release first, and the sentence I will use:"}]'::jsonb, array['planning', 'boundaries', 'stress']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('rotating-shift-sleep-anchor-sheet', 'Rotating Shift Sleep Anchor Sheet', 'worksheet'::resource_kind, 'A planner for a client on rotating shifts that fixes one anchor sleep block, a light plan and a wind-down the schedule cannot move.', 'Use it to give a shift worker a steady piece of sleep when the rest of the schedule keeps changing.', array['Adults']::text[], '30 minutes to plan, one rotation to use', 'Rotating shifts break every ordinary sleep rule, so the sheet asks for what can stay fixed: a core block of four or five hours that falls inside every version of the schedule, a bright-light plan for waking and a dark plan for sleeping, a wind-down routine that travels across shifts, and what the household agrees to protect. Review it after one full rotation and adjust the anchor block rather than abandoning it. Watch for a client using long naps to catch up, which often pushes the next sleep later.', '[{"id": "f0", "type": "textarea", "label": "My shift pattern for the next rotation, written out by day:"}, {"id": "f1", "type": "textarea", "label": "The core sleep block that fits inside every version of my schedule:"}, {"id": "f2", "type": "textarea", "label": "My light plan: when I get bright light and when I block it:"}, {"id": "f3", "type": "textarea", "label": "The wind-down I can do before any sleep, day or night, in the same order:"}, {"id": "f4", "type": "textarea", "label": "What I need from the people I live with to protect the anchor block:"}, {"id": "f5", "type": "textarea", "label": "After one rotation: which nights the anchor held, and what to adjust:"}]'::jsonb, array['sleep', 'routines', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('sandwich-generation-pull-map-sheet', 'Sandwich Generation Pull Map Sheet', 'worksheet'::resource_kind, 'A map for a client caring for children and aging parents at once, showing where the pulls land each week and where help could go.', 'Use it to help a client squeezed between two generations see the full load and find the one ask that would ease it.', array['Adults']::text[], '45 minutes', 'Draw the week as a grid and have the client mark every pull: school runs, a parent''s appointments, calls from a sibling, the hour that belongs to nobody. Then mark who else could carry each item and what has stopped the client from asking. The map usually shows the same two or three days collapsing under everything. Watch for guilt that frames any ask as abandonment, and for a sibling split that the client has never actually proposed out loud.', '[{"id": "f0", "type": "textarea", "label": "The pulls from my children this week, day by day:"}, {"id": "f1", "type": "textarea", "label": "The pulls from my parent or parents this week, day by day:"}, {"id": "f2", "type": "textarea", "label": "The days where the two sets collide, and what happens on those days:"}, {"id": "f3", "type": "textarea", "label": "Each pull that someone else could carry, and who:"}, {"id": "f4", "type": "textarea", "label": "What has stopped me from asking, in my own words:"}, {"id": "f5", "type": "textarea", "label": "The one ask I will make this week, to whom, and when:"}]'::jsonb, array['family', 'stress', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('social-debt-ledger-of-owed-replies-and-thanks', 'Social Debt Ledger of Owed Replies and Thanks', 'worksheet'::resource_kind, 'A ledger of the replies, thank-you notes and invitations a client owes, with a short plan to clear them a few at a time.', 'Use it to help a client whose avoidance of small social debts has grown into dread clear the backlog without a marathon.', array['Adults', 'Teens']::text[], '30 minutes to list, one week to clear', 'Unanswered invitations and unsent thanks pile up quietly and then feel too late to send. Have the client list every item, mark how old it is and what they fear the recipient now thinks, then pick a daily number, usually two, and a one-line template for the overdue ones that names the delay without a long apology. Watch for a client who wants to clear everything in one sitting and then avoids the sheet, and for the belief that a late reply is worse than none.', '[{"id": "f0", "type": "textarea", "label": "Every reply, thank-you or RSVP I owe right now, and roughly how old each is:"}, {"id": "f1", "type": "textarea", "label": "For the oldest ones: what I imagine the person thinks of me now:"}, {"id": "f2", "type": "textarea", "label": "My one-line opener for an overdue message that names the delay without a long apology:"}, {"id": "f3", "type": "textarea", "label": "How many I will clear each day this week:"}, {"id": "f4", "type": "textarea", "label": "The replies I sent and what, if anything, came back:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the dread as the list shortens:"}]'::jsonb, array['avoidance', 'communication', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('missed-the-bus-day-ruined-thought-record', 'Missed the Bus Day Ruined Thought Record', 'cbt'::resource_kind, 'A thought record for the small early setback that gets read as the whole day going wrong, with a hour-by-hour check against reality.', 'Use it to catch all-or-nothing thinking at the moment it fires, on an ordinary setback, where it is easiest to test.', array['Adults', 'Teens']::text[], '15 minutes, repeated after small setbacks', 'A missed bus, a spilled coffee or a forgotten badge is a clean place to teach the thought record because the stakes are low and the prediction is testable the same day. The client writes the setback, the thought about the day, the certainty rating, and then at bedtime rates how the day actually went hour by hour. Compare the morning verdict with the evening record. Watch for the client who turns the exercise into a new standard about never being late.', '[{"id": "f0", "type": "textarea", "label": "The small setback, and the time it happened:"}, {"id": "f1", "type": "textarea", "label": "The thought I had about the rest of the day, word for word:"}, {"id": "f2", "type": "textarea", "label": "How sure I was, zero to one hundred, that the day was ruined:"}, {"id": "f3", "type": "textarea", "label": "At bedtime: how the day actually went, hour by hour:"}, {"id": "f4", "type": "textarea", "label": "Which parts of the day were fine, good or even better than usual:"}, {"id": "f5", "type": "textarea", "label": "My revised rule about what one setback means for a day:"}]'::jsonb, array['core CBT', 'thinking traps', 'thought record']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('neighbor-did-not-wave-back-thought-record', 'Neighbor Did Not Wave Back Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a neighbor or acquaintance does not wave or greet, with the mind-reading laid out and tested.', 'Use it to work on mind reading with a situation small enough that the client can gather real information afterward.', array['Adults', 'Teens']::text[], '15 minutes', 'The unreturned wave is a tidy example of mind reading: a neutral fact, a confident story about what the other person thinks, and no check. The client records the moment, the explanation they landed on, and how it changed what they did next, then lists other explanations and, where possible, what they learned the next time they saw the person. Watch for a client who avoids the neighbor afterward, because avoidance quietly confirms the story.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts, with no interpretation:"}, {"id": "f1", "type": "textarea", "label": "The explanation my mind produced, and how sure I felt:"}, {"id": "f2", "type": "textarea", "label": "What I did differently afterward because of that explanation:"}, {"id": "f3", "type": "textarea", "label": "Five other explanations that fit the same facts:"}, {"id": "f4", "type": "textarea", "label": "What I actually learned the next time I saw them, if anything:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the original explanation now:"}]'::jsonb, array['core CBT', 'thinking traps', 'automatic thoughts']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('canceled-plans-relief-or-rejection-sort-sheet', 'Canceled Plans Relief or Rejection Sort Sheet', 'cbt'::resource_kind, 'A sheet for the mixed reaction when plans fall through, separating relief, rejection and the thoughts that turn one into the other.', 'Use it to help a client notice how a canceled plan becomes evidence about their worth, and test that step.', array['Adults', 'Teens']::text[], '20 minutes', 'When a friend cancels, many clients feel relief and rejection in the same minute and then build a story on the rejection half. The sheet asks for the facts of the cancellation, each feeling named separately with its own thought, the evidence that the cancellation was about them, and the evidence it was not. Finish with what they will do with the freed evening. Watch for a client who treats their own relief as proof they are a bad friend.', '[{"id": "f0", "type": "textarea", "label": "The plan, who canceled, and exactly what they said:"}, {"id": "f1", "type": "textarea", "label": "The relief I felt, and the thought that came with it:"}, {"id": "f2", "type": "textarea", "label": "The rejection I felt, and the thought that came with it:"}, {"id": "f3", "type": "textarea", "label": "Evidence the cancellation was about me:"}, {"id": "f4", "type": "textarea", "label": "Evidence it was about their day, their energy or something else:"}, {"id": "f5", "type": "textarea", "label": "What I will do with the time, and whether I will suggest another date:"}]'::jsonb, array['core CBT', 'thinking traps', 'relationships']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('ask-the-store-for-a-discount-experiment-sheet', 'Ask the Store for a Discount Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment that has the client ask a shop or service for a small discount and compares the feared reaction with the real one.', 'Use it to test beliefs about asking, being a nuisance and being refused, in a setting with a stranger and low stakes.', array['Adults', 'Teens']::text[], 'One week', 'Asking for a discount on a damaged item, a bundle or a loyalty price is a low-cost way to test rules like asking makes me a nuisance or refusal would be humiliating. The client writes the prediction, including how the clerk will look and how long the embarrassment will last, then asks and records what happened. A refusal is still useful data about how refusal actually feels. Watch for a client who picks a situation where a yes is guaranteed and learns nothing.', '[{"id": "f0", "type": "textarea", "label": "The rule I hold about asking for things I was not offered:"}, {"id": "f1", "type": "textarea", "label": "Where I will ask, what I will say, and what I will ask for:"}, {"id": "f2", "type": "textarea", "label": "My prediction: the clerk''s reaction, how I will feel, and how long it will last:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, including the words they used:"}, {"id": "f4", "type": "textarea", "label": "How I felt during and ten minutes after, zero to one hundred:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about my rule, and the next ask I could try:"}]'::jsonb, array['behavioral experiment', 'predictions', 'assertiveness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('only-remembering-the-criticism-mental-filter-sheet', 'Only Remembering the Criticism Mental Filter Sheet', 'cbt'::resource_kind, 'A sheet for the day the one critical comment swallowed the rest, listing every piece of feedback received and how much attention each got.', 'Use it to show a client how the mental filter works on real feedback and to practice weighting it fairly.', array['Adults', 'Teens']::text[], '20 minutes after a review, meeting or performance', 'After a review or a performance, clients often report only the critical line. The sheet has them list every comment they actually received, positive, neutral and critical, estimate how many minutes they have spent on each since, and then write a summary that gives each comment weight in proportion to how often it appeared. Compare the summary with the one they walked in with. Watch for a client who recasts neutral comments as veiled criticism to keep the filter intact.', '[{"id": "f0", "type": "textarea", "label": "The event, and the single comment I keep replaying:"}, {"id": "f1", "type": "textarea", "label": "Every other comment I received, positive, neutral and critical:"}, {"id": "f2", "type": "textarea", "label": "Roughly how many minutes I have spent thinking about each since:"}, {"id": "f3", "type": "textarea", "label": "A summary of the feedback that gives each comment fair weight:"}, {"id": "f4", "type": "textarea", "label": "What I would conclude from this feedback if it were about a colleague:"}, {"id": "f5", "type": "textarea", "label": "One thing I will actually do with the critical comment:"}]'::jsonb, array['core CBT', 'thinking traps', 'evidence']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('wrestling-the-octopus-metaphor-page', 'Wrestling the Octopus Metaphor Page', 'act'::resource_kind, 'A metaphor page comparing the fight with difficult thoughts to wrestling an octopus, where every arm pinned frees another.', 'Use it to help a client who argues with their thoughts all day notice what the struggle costs and try letting the arms move.', array['Adults', 'Teens']::text[], '20 minutes', 'Pinning one worry down frees another; by the time the client has argued with three, two more have wrapped around. The page asks the client to name their octopus''s arms, describe what wrestling has cost in a typical day, and then try a different stance: let the arms move while the client goes on with what they were doing. Debrief what it was like to stop pinning. Watch for the client who hears the metaphor as instruction to ignore thoughts, which is another kind of wrestling.', '[{"id": "f0", "type": "textarea", "label": "The arms of my octopus: the thoughts I spend the most time fighting:"}, {"id": "f1", "type": "textarea", "label": "What the wrestling looks like, in behavior, on an ordinary day:"}, {"id": "f2", "type": "textarea", "label": "What it has cost me this week in time, energy and things left undone:"}, {"id": "f3", "type": "textarea", "label": "One activity I did this week while letting the arms move instead of pinning them:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the arms when I stopped wrestling:"}, {"id": "f5", "type": "textarea", "label": "What I want to do with the energy that wrestling used to take:"}]'::jsonb, array['core ACT', 'defusion', 'metaphor']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('pushy-salesperson-mind-defusion-page', 'Pushy Salesperson Mind Defusion Page', 'act'::resource_kind, 'A defusion page that treats the mind''s urgent pitches as a pushy salesperson at the door, heard politely and not necessarily bought.', 'Use it to give a client a way to hear an insistent thought without buying what it is selling.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write their mind''s most common pitches as a salesperson would deliver them, complete with the urgency and the limited-time offer. Then they practice a doorstep response: hearing the pitch out, thanking the salesperson, and closing the door without the product. The page asks what the mind is selling, what buying it has cost before, and what the client wants to spend on instead. Watch for a client who slams the door, which is suppression; the point is the polite no.', '[{"id": "f0", "type": "textarea", "label": "My mind''s three most frequent sales pitches, written as a salesperson would say them:"}, {"id": "f1", "type": "textarea", "label": "The urgency words my mind uses to close the sale:"}, {"id": "f2", "type": "textarea", "label": "What buying these pitches has cost me before:"}, {"id": "f3", "type": "textarea", "label": "My doorstep line for hearing the pitch and not buying:"}, {"id": "f4", "type": "textarea", "label": "One time this week I heard the pitch and went on with my plan anyway:"}, {"id": "f5", "type": "textarea", "label": "What I would rather spend my attention on:"}]'::jsonb, array['core ACT', 'defusion', 'metaphor']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('buying-the-thought-versus-renting-it-page', 'Buying the Thought Versus Renting It Page', 'act'::resource_kind, 'A page that separates thoughts the client has bought outright from thoughts they could hold briefly and hand back.', 'Use it to give a client language for the difference between having a thought and taking it as truth.', array['Adults', 'Teens']::text[], '20 minutes', 'A thought that is bought runs the day; a thought that is rented is held, looked at and returned. The page has the client list the thoughts they have bought over the years, what owning each has cost, and then practice renting a current one: noticing it, saying I am having the thought that, and setting it down. Watch for a client who argues about the truth of the thought, which is still a purchase; the question is workability, not accuracy.', '[{"id": "f0", "type": "textarea", "label": "Thoughts I have bought outright, so that they run my days:"}, {"id": "f1", "type": "textarea", "label": "What owning each of those thoughts has cost me:"}, {"id": "f2", "type": "textarea", "label": "A thought I will try renting this week instead of buying:"}, {"id": "f3", "type": "textarea", "label": "The words I will use when I notice it: I am having the thought that…"}, {"id": "f4", "type": "textarea", "label": "What was different about my actions when I rented it rather than bought it:"}, {"id": "f5", "type": "textarea", "label": "A thought I am ready to return to the store:"}]'::jsonb, array['core ACT', 'defusion', 'workability']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('noticing-who-is-noticing-page', 'Noticing Who Is Noticing Page', 'act'::resource_kind, 'A self-as-context page that moves the client''s attention from what they notice to the part of them that is doing the noticing.', 'Use it to help a client make contact with the observing self when thoughts and feelings have become the whole picture.', array['Adults', 'Teens']::text[], '15 minutes, repeated daily', 'Walk the client through noticing a sound, a sensation, a thought, and then asking who noticed each one. The page records what they noticed and, each time, the moment of turning to the noticer. Keep it experiential; it is not a question with a verbal answer. Repeat it daily for a week, two minutes at a time. Watch for a client who reports that nothing happened, which often means they were looking for a feeling rather than noticing the noticing.', '[{"id": "f0", "type": "textarea", "label": "A sound I noticed just now, and who noticed it:"}, {"id": "f1", "type": "textarea", "label": "A sensation in my body I noticed, and who noticed it:"}, {"id": "f2", "type": "textarea", "label": "A thought that passed, and who noticed it:"}, {"id": "f3", "type": "textarea", "label": "Something about the one who notices that has stayed the same since childhood:"}, {"id": "f4", "type": "textarea", "label": "What happened to the thought or feeling while I was attending to the noticer:"}, {"id": "f5", "type": "textarea", "label": "One moment this week I stepped into the noticer when a feeling was large:"}]'::jsonb, array['core ACT', 'self-as-context', 'mindfulness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('reason-giving-lawyer-who-never-rests-page', 'Reason-Giving Lawyer Who Never Rests Page', 'act'::resource_kind, 'A page that casts the mind''s reasons for not acting as a lawyer who will argue any case, so the client can hear the brief and act anyway.', 'Use it to help a client who has a good reason for everything notice that reasons are not the same as decisions.', array['Adults', 'Teens']::text[], '20 minutes', 'The mind can produce a convincing reason against any valued action, and a convincing reason for it a minute later. Have the client write the lawyer''s full case against one step they have been avoiding, then thank the lawyer, note that the brief is well argued, and decide separately whether to take the step. The page tracks reasons given, steps taken anyway, and what happened. Watch for a client who tries to out-argue the lawyer; the lawyer always has a reply.', '[{"id": "f0", "type": "textarea", "label": "The valued step I have been putting off:"}, {"id": "f1", "type": "textarea", "label": "The lawyer''s full case against taking it, every reason, however small:"}, {"id": "f2", "type": "textarea", "label": "Which of these reasons would still be true a year from now:"}, {"id": "f3", "type": "textarea", "label": "My line for thanking the lawyer and ending the hearing:"}, {"id": "f4", "type": "textarea", "label": "Did I take the step this week, with the reasons still in the room?"}, {"id": "f5", "type": "textarea", "label": "What happened, and what the lawyer said afterward:"}]'::jsonb, array['core ACT', 'defusion', 'committed action']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('observe-skill-at-a-red-light-card', 'Observe Skill at a Red Light Card', 'dbt'::resource_kind, 'A card for practicing the mindfulness observe skill in the sixty seconds at a red light, with no phone and no commentary.', 'Use it to give a client a daily, built-in moment to practice observing before they try it under pressure.', array['Adults', 'Teens']::text[], 'One minute, several times a day for a week', 'Red lights are short, frequent and empty, which makes them a good training ground for the observe skill. The card asks the client to notice five things through the senses while stopped, without naming them good or bad, and to notice the urge to reach for the phone as one more thing to observe. Review how many lights they used and what they noticed about the urge. Watch for a client who turns it into a performance review of their own attention.', '[{"id": "f0", "type": "textarea", "label": "Five things I observed at a red light today, through my senses, without judging them:"}, {"id": "f1", "type": "textarea", "label": "The urge I noticed, to reach for the phone or anything else, and what it felt like in my body:"}, {"id": "f2", "type": "textarea", "label": "What it was like to let the light change without having done anything:"}, {"id": "f3", "type": "textarea", "label": "Roughly how many red lights I used for this today:"}, {"id": "f4", "type": "textarea", "label": "What changed about the first minute of the rest of the drive:"}]'::jsonb, array['core DBT', 'mindfulness', 'routines']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('dialectical-thinking-both-sides-of-a-stuck-opinion-sheet', 'Dialectical Thinking Both Sides of a Stuck Opinion Sheet', 'dbt'::resource_kind, 'A sheet that takes one opinion the client is stuck on and writes the truth in the opposing view until both can be held at once.', 'Use it to practice dialectical thinking on an opinion that keeps the client in conflict with someone.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick an opinion that has become a wall: a sibling is selfish, the manager does not care. The client writes their position and the grain of truth in it, then the opposing position and the grain of truth in that, and finally a both-and sentence that keeps what is true on each side. Watch for a both-and that is really a disguised concession, and for the client who refuses to find any truth on the other side; start with a smaller opinion if so.', '[{"id": "f0", "type": "textarea", "label": "The opinion I am stuck on, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "What is true in my position, and what it protects:"}, {"id": "f2", "type": "textarea", "label": "The opposing position, stated as fairly as its holder would state it:"}, {"id": "f3", "type": "textarea", "label": "What is true in that position, even a little:"}, {"id": "f4", "type": "textarea", "label": "A both-and sentence that keeps the truth on each side:"}, {"id": "f5", "type": "textarea", "label": "What I could do differently if I acted from the both-and sentence:"}]'::jsonb, array['core DBT', 'dialectics', 'conflict']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('loving-kindness-toward-a-difficult-person-card', 'Loving Kindness Toward a Difficult Person Card', 'dbt'::resource_kind, 'A loving kindness card that moves from an easy person to a neutral one to a difficult one, with the client''s own phrases.', 'Use it to help a client loosen a grudge or resentment that keeps their own emotion mind running.', array['Adults']::text[], '10 minutes daily for two weeks', 'The client chooses four short phrases of goodwill and directs them first to themselves, then to someone easy to love, then to a neutral person like a cashier, and only then to the difficult person. The card asks them to notice what the body does at each step and to stop at neutral on days when the difficult person is too hot. Watch for a client who hears this as forgiving or excusing; it is about what resentment costs them, not about the other person.', '[{"id": "f0", "type": "textarea", "label": "My four phrases of goodwill, in my own words:"}, {"id": "f1", "type": "textarea", "label": "Who I will use as my easy person, my neutral person and my difficult person:"}, {"id": "f2", "type": "textarea", "label": "What my body did when I reached the difficult person today:"}, {"id": "f3", "type": "textarea", "label": "Days I stopped at the neutral person, and why that was the wise choice:"}, {"id": "f4", "type": "textarea", "label": "What has changed in how often the difficult person shows up in my thoughts:"}]'::jsonb, array['core DBT', 'mindfulness', 'self-compassion']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('doing-mind-and-being-mind-balance-sheet', 'Doing Mind and Being Mind Balance Sheet', 'dbt'::resource_kind, 'A sheet that maps the client''s week between doing mind and being mind and plans a shift toward the middle path.', 'Use it to help a client who is always achieving or always drifting find the balance between the two.', array['Adults', 'Teens']::text[], '30 minutes', 'Doing mind is focused on goals and getting through; being mind is focused on the present moment and experiencing it. The sheet has the client estimate the hours of each in a typical week, name the costs of being stuck on one side, and plan one activity to bring more of the missing side. Watch for the client who adds being mind as another task to complete, and for the one who uses being mind to avoid work that needs doing.', '[{"id": "f0", "type": "textarea", "label": "Where my week sits between doing mind and being mind, as a rough split:"}, {"id": "f1", "type": "textarea", "label": "What being stuck mostly on my side has cost me:"}, {"id": "f2", "type": "textarea", "label": "What the other side would give me if I had a little more of it:"}, {"id": "f3", "type": "textarea", "label": "One activity this week to add the missing side, and when:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I was in that activity:"}, {"id": "f5", "type": "textarea", "label": "The middle path sentence that describes the balance I am aiming for:"}]'::jsonb, array['core DBT', 'mindfulness', 'wise mind']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('finding-my-own-paced-breathing-count-sheet', 'Finding My Own Paced Breathing Count Sheet', 'dbt'::resource_kind, 'A sheet for discovering the client''s own slow breathing count by trial, so paced breathing fits their lungs rather than a script.', 'Use it to set up paced breathing in a way the client will keep, with a count that feels right to them.', array['Adults', 'Teens']::text[], '20 minutes in session, then daily', 'A fixed count does not fit everyone, and a client who feels air hungry on someone else''s count will drop the skill. Try three counts in session, each with the out-breath longer than the in-breath, and have the client rate comfort and calm after a minute of each. Record the winner and where they will practice it. Watch for breath holding and for a client who tries to make the count as slow as possible; comfortable beats impressive.', '[{"id": "f0", "type": "textarea", "label": "The three counts I tried, in-breath and out-breath, and how each felt after a minute:"}, {"id": "f1", "type": "textarea", "label": "The count that felt most comfortable, which I will keep:"}, {"id": "f2", "type": "textarea", "label": "Where in my body I notice the slowing, if anywhere:"}, {"id": "f3", "type": "textarea", "label": "Two times a day I will practice it when I am already calm:"}, {"id": "f4", "type": "textarea", "label": "The first stressful moment I used it, and what happened:"}]'::jsonb, array['core DBT', 'distress tolerance', 'breathing']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('snoring-and-separate-bedrooms-talk-sheet-for-partners', 'Snoring and Separate Bedrooms Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for partners deciding how to handle snoring or sleep disruption, including separate rooms, without reading it as distance.', 'Use it to help a couple solve a sleep problem practically while naming what each fears it means.', array['Couples']::text[], '40 minutes', 'Sleep disruption from snoring, restlessness or mismatched schedules often goes unaddressed because one partner hears separate rooms as a verdict on the relationship. Each partner writes what the sleep problem costs them and what they fear a change would mean, then they list options from earplugs to a second bedroom with a connection ritual attached to each. Watch for the snoring partner''s shame, and for the other partner''s resentment that has been building silently for years.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what the sleep situation costs me, and what I fear a change would mean:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what the sleep situation costs me, and what I fear a change would mean:"}, {"id": "f2", "type": "textarea", "label": "Every option we can think of, from small adjustments to separate rooms:"}, {"id": "f3", "type": "textarea", "label": "For the options that involve sleeping apart: the connection ritual we would attach, before bed and in the morning:"}, {"id": "f4", "type": "textarea", "label": "The option we will try for two weeks:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how each of us slept and how close we felt:"}]'::jsonb, array['couples', 'sleep', 'communication']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('backseat-driver-agreement-for-partners', 'Backseat Driver Agreement for Partners', 'couples'::resource_kind, 'An agreement for the partner who comments on the other''s driving and the partner who bristles, with what each will do instead.', 'Use it to turn a small recurring car fight into a plan both partners can keep on the next drive.', array['Couples']::text[], '30 minutes', 'Car comments are small and constant, and they land in a space neither partner can leave. The commenting partner writes what they fear when they comment and the one thing they truly need to be able to say; the driving partner writes what the comments feel like and what they would hear without bristling. Together they set a single agreed phrase for genuine safety concerns and a rule for everything else. Watch for the drive home from a hard visit, where comments are often about something else.', '[{"id": "f0", "type": "textarea", "label": "Partner who comments: what I feel in the passenger seat, and what I fear when I speak up:"}, {"id": "f1", "type": "textarea", "label": "Partner who drives: what the comments feel like to me, and what I hear underneath them:"}, {"id": "f2", "type": "textarea", "label": "The one phrase we agree means a real safety concern, to be used sparingly:"}, {"id": "f3", "type": "textarea", "label": "What the commenting partner will do with the urge to speak about everything else:"}, {"id": "f4", "type": "textarea", "label": "What the driving partner will do when the agreed phrase is used:"}, {"id": "f5", "type": "textarea", "label": "How our next three drives went, honestly:"}]'::jsonb, array['couples', 'conflict', 'communication']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('work-trip-reentry-evening-plan-for-partners', 'Work Trip Reentry Evening Plan for Partners', 'couples'::resource_kind, 'A plan for the first evening after one partner returns from a work trip, with the home partner''s and the traveler''s needs both named.', 'Use it to stop the return from a trip turning into the fight that both partners have come to expect.', array['Couples']::text[], '25 minutes', 'The traveler wants to decompress; the partner at home wants relief and acknowledgment; both arrive at the door depleted. Each writes what the first hour home usually looks like, what they actually need from it, and what they could give. Then they draft the first evening: who handles the kids or dinner, when the trip debrief happens, and a small ritual that marks the return. Watch for a traveler who assumes the home partner had it easy, and for a home partner who stores up grievances for the doorstep.', '[{"id": "f0", "type": "textarea", "label": "Traveling partner: what I need in the first hour home, and what I can give:"}, {"id": "f1", "type": "textarea", "label": "Home partner: what I need in the first hour, and what I can give:"}, {"id": "f2", "type": "textarea", "label": "How the return evening usually goes now, in both of our words:"}, {"id": "f3", "type": "textarea", "label": "Our plan for the next return: who does what, and when we talk about the trip:"}, {"id": "f4", "type": "textarea", "label": "A small ritual that marks the return for both of us:"}, {"id": "f5", "type": "textarea", "label": "After the next trip: what worked and what we will change:"}]'::jsonb, array['couples', 'planning', 'connection']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('pet-care-load-split-sheet-for-partners', 'Pet Care Load Split Sheet for Partners', 'couples'::resource_kind, 'A sheet that lists every task a shared pet needs, who does each now, and how the partners want it split.', 'Use it to make the invisible pet work visible and settle a quiet resentment before it becomes a fight.', array['Couples']::text[], '30 minutes', 'Pets generate dozens of small tasks, and one partner usually carries most of them while both describe the pet as shared. Have the partners list every task, from walks to vet appointments to the midnight accident, mark who actually did each last week, and each write what they feel seeing the tally. Then they rebalance, including tasks that one partner is happy to keep. Watch for the partner who wanted the pet treating the other''s help as a favor rather than a share.', '[{"id": "f0", "type": "textarea", "label": "Every task our pet needs in a week, including the rare ones:"}, {"id": "f1", "type": "textarea", "label": "Who actually did each task last week:"}, {"id": "f2", "type": "textarea", "label": "Partner one: what I feel seeing the tally:"}, {"id": "f3", "type": "textarea", "label": "Partner two: what I feel seeing the tally:"}, {"id": "f4", "type": "textarea", "label": "The split we both agree to, including what each of us is glad to keep:"}, {"id": "f5", "type": "textarea", "label": "How we will handle the tasks nobody wants, like early walks in the rain:"}]'::jsonb, array['couples', 'fairness', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('birthday-expectations-talk-sheet-for-partners', 'Birthday Expectations Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for partners whose birthdays keep disappointing one of them, with what each grew up expecting and what each wants now.', 'Use it to replace the yearly birthday letdown with a plan both partners understand.', array['Couples']::text[], '30 minutes', 'Birthdays carry rules from each partner''s childhood: a big party, a quiet dinner, a surprise, nothing at all. Each writes what birthdays were like growing up, what they secretly hope for now, and what they assumed the other knew. They then agree what the next two birthdays will look like, including who plans and how much is a surprise. Watch for a partner who says they do not care and then does, and for the belief that having to ask spoils it.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what birthdays were like growing up, and what I hope for now:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what birthdays were like growing up, and what I hope for now:"}, {"id": "f2", "type": "textarea", "label": "What each of us assumed the other already knew:"}, {"id": "f3", "type": "textarea", "label": "How the last birthday went, from each side, without blame:"}, {"id": "f4", "type": "textarea", "label": "The plan for each of our next birthdays, including who plans and how much is a surprise:"}, {"id": "f5", "type": "textarea", "label": "What we will do if the day does not go as planned:"}]'::jsonb, array['couples', 'communication', 'appreciation']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('cotton-ball-blow-race-breathing-play', 'Cotton Ball Blow Race Breathing Play', 'kids'::resource_kind, 'A breathing game where the child blows a cotton ball along a table track with long slow breaths while the parent referees.', 'Use it to teach a young child a long out-breath without ever saying the word breathing.', array['Children']::text[], '10 minutes, repeated at home', 'Tape a start and finish line on a table and give the child a cotton ball. The rule is that only long slow blows count; a hard puff sends the ball off the table and back to the start. The parent referees, calls out slow and long, and takes a turn too, exaggerating their own slow breath. Afterward the parent asks where the child felt the slow breath in their body. Watch for a child who gets frantic and tries to win with force; slow the track down by adding a curve.', '[{"id": "f0", "type": "textarea", "label": "Draw your race track with the start and finish line:"}, {"id": "f1", "type": "textarea", "label": "How many slow blows did it take to get the cotton ball to the finish?"}, {"id": "f2", "type": "textarea", "label": "What happened when you blew too hard?"}, {"id": "f3", "type": "textarea", "label": "Where in your body did you feel the slow breath?"}, {"id": "f4", "type": "textarea", "label": "When is a time you could use a slow cotton ball breath, even without the cotton ball?"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('shaving-cream-feelings-writing-tray-play', 'Shaving Cream Feelings Writing Tray Play', 'kids'::resource_kind, 'A sensory play where the child writes or draws feelings in a tray of shaving cream and wipes them smooth when they are ready.', 'Use it to let a child name and let go of a feeling with their hands before they have words for it.', array['Children']::text[], '20 minutes', 'Spread shaving cream on a tray and invite the child to draw the feeling they have right now: a shape, a face, a scribble, a word if they write. The parent sits beside them, names what they see without correcting it, and draws their own feeling in a corner. When the child is ready, they smooth the tray flat and can start again. Watch for a child who smooths everything instantly; that is fine, and the parent can simply notice it out loud.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe the feeling you made in the shaving cream:"}, {"id": "f1", "type": "textarea", "label": "What did the feeling look like: big or small, pointy or round?"}, {"id": "f2", "type": "textarea", "label": "What did your grown-up draw in their corner?"}, {"id": "f3", "type": "textarea", "label": "What did it feel like to smooth the tray flat?"}, {"id": "f4", "type": "textarea", "label": "Which feeling would you like to make next time?"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('paper-plate-feelings-clock-craft', 'Paper Plate Feelings Clock Craft', 'kids'::resource_kind, 'A paper plate clock with feelings instead of numbers and a moving hand the child sets through the day, with a parent check-in.', 'Use it to give a family a quick, wordless way for a child to show how they feel at set points in the day.', array['Children']::text[], '30 minutes to make, daily to use', 'The child draws six to eight feelings around a paper plate, attaches a hand with a brass fastener, and decorates the clock. It goes on the fridge, and the family agrees on two or three clock times, such as after school and before bed, when the child sets the hand and the parent asks one question about why. The parent sets their own hand on a second plate so the child sees adults have feelings too. Watch for a parent who argues with the setting; the hand is where the child says it is.', '[{"id": "f0", "type": "textarea", "label": "Draw the feelings you put around your clock:"}, {"id": "f1", "type": "textarea", "label": "Which times of day will you set your clock?"}, {"id": "f2", "type": "textarea", "label": "Where was your hand after school today, and what made it point there?"}, {"id": "f3", "type": "textarea", "label": "Where was your grown-up''s hand?"}, {"id": "f4", "type": "textarea", "label": "What is one thing that helps move your hand when it is on a hard feeling?"}]'::jsonb, array['children', 'craft', 'emotion identification']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('feelings-fishing-pond-magnet-craft', 'Feelings Fishing Pond Magnet Craft', 'kids'::resource_kind, 'A craft that makes paper fish with feelings and situations on them and a magnet rod, then a fishing game with the parent.', 'Use it to practice naming feelings and matching them to situations through a game a young child will ask to play again.', array['Children']::text[], '30 minutes to make, 15 minutes to play', 'The child cuts out paper fish, draws a feeling face on half and a situation on the rest, and the parent attaches a paper clip to each. A stick, string and magnet make the rod. To play, the child catches a fish and either names the feeling or says what feeling the situation might bring, and the parent takes turns too. Keep situations ordinary: a lost toy, a friend coming over. Watch for a parent who turns every catch into a lesson; one question per fish is plenty.', '[{"id": "f0", "type": "textarea", "label": "Draw some of the fish you made and the feelings on them:"}, {"id": "f1", "type": "textarea", "label": "Which situation fish did you catch, and what feeling did you match to it?"}, {"id": "f2", "type": "textarea", "label": "Which fish did your grown-up catch, and what did they say?"}, {"id": "f3", "type": "textarea", "label": "Which feeling fish is the hardest one to talk about?"}, {"id": "f4", "type": "textarea", "label": "What would you add to the pond next time?"}]'::jsonb, array['children', 'craft', 'emotion identification']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('grow-a-bean-in-a-jar-patience-watch-craft', 'Grow a Bean in a Jar Patience Watch Craft', 'kids'::resource_kind, 'A craft that sprouts a bean in a jar with a daily drawing log, so a child practices waiting for something they cannot rush.', 'Use it to give a child who struggles to wait a living thing to watch that only changes slowly.', array['Children']::text[], '15 minutes to set up, five minutes daily for two weeks', 'A dried bean, a jar, a damp paper towel and a sunny window. The child checks once a day, draws what they see and writes or dictates one word about how waiting feels. The parent sets the check time, keeps the towel damp and resists the urge to promise when the sprout will appear. The first days of nothing are the point. Watch for a child who wants to dig the bean out to check on it; the parent can name that urge and ask what the bean needs instead.', '[{"id": "f0", "type": "textarea", "label": "Draw your bean jar on the first day:"}, {"id": "f1", "type": "textarea", "label": "Draw what you see on each day you check:"}, {"id": "f2", "type": "textarea", "label": "On the days when nothing changed, how did waiting feel?"}, {"id": "f3", "type": "textarea", "label": "What did you feel on the day the sprout showed?"}, {"id": "f4", "type": "textarea", "label": "What else in your life is like the bean, growing slowly where you cannot see it?"}]'::jsonb, array['children', 'craft', 'distress tolerance']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('fishbowl-question-draw-game', 'Fishbowl Question Draw Game', 'game'::resource_kind, 'A group game where players draw folded questions from a bowl, answer or pass once, and the group finds who shares the answer.', 'Use it to warm up a new group with questions that get a little deeper each round, with a pass rule that keeps it safe.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Prepare three colors of folded questions: easy, medium and deeper. Round one uses only easy questions; each player draws, reads aloud and answers in one or two sentences, and then asks who else in the circle shares the answer. Each player gets one pass per game, no reason needed. The group moves up a color when everyone has had a turn. Debrief what it was like to hear overlap. Watch for players who answer with a joke every time; let it be, and notice whether it shifts by round three.', '[{"id": "f0", "type": "textarea", "label": "Which question did you draw, and what did you answer?"}, {"id": "f1", "type": "textarea", "label": "Who in the group shared your answer, and did that surprise you?"}, {"id": "f2", "type": "textarea", "label": "Did you use your pass? What was it like to have one?"}, {"id": "f3", "type": "textarea", "label": "Which round felt the most honest to you?"}, {"id": "f4", "type": "textarea", "label": "One thing you learned about someone in this group:"}]'::jsonb, array['group', 'connection', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('fortunately-unfortunately-story-circle-game', 'Fortunately Unfortunately Story Circle Game', 'game'::resource_kind, 'A story game where players alternate fortunately and unfortunately sentences, then debrief how a story survives both.', 'Use it to give a group a playful rehearsal of flexible thinking, with every setback followed by a turn.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'One player starts a story with a neutral sentence. The next must begin with unfortunately and add a setback; the next with fortunately and add a turn; and so on around the circle, with each sentence building on the one before. Three rounds, then stop wherever the story is. The debrief asks which was easier to think of, setbacks or turns, and what that says about the mind''s default. Watch for a group that makes the unfortunately sentences catastrophic; keep the tone light and the sentences short.', '[{"id": "f0", "type": "textarea", "label": "How did our story begin, and where did it end up?"}, {"id": "f1", "type": "textarea", "label": "Was it easier for you to think of an unfortunately or a fortunately? Why do you think that is?"}, {"id": "f2", "type": "textarea", "label": "Which fortunately turn in the story did you like best?"}, {"id": "f3", "type": "textarea", "label": "What is a real situation where you could add a fortunately sentence?"}, {"id": "f4", "type": "textarea", "label": "What did the story teach you about how setbacks and turns take turns?"}]'::jsonb, array['group', 'thinking traps', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('pass-the-parcel-prompt-layers-game', 'Pass the Parcel Prompt Layers Game', 'game'::resource_kind, 'A group game where a wrapped parcel passes around to music and each layer unwrapped reveals a prompt the holder answers.', 'Use it to give a group a reason to answer reflective prompts with the fun of a childhood party game.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Wrap a small prize in eight to ten layers of paper, with a prompt tucked into each layer: a strength you noticed in someone here, a thing that helped you this week. Play music while the parcel passes; when it stops, the holder unwraps one layer, reads the prompt and answers it, and play resumes. The last layer''s prize is shared with the group. Watch for a group that rushes the answers to get to the prize; pause the music until the answer is complete.', '[{"id": "f0", "type": "textarea", "label": "Which prompt did you unwrap, and what did you answer?"}, {"id": "f1", "type": "textarea", "label": "Which answer from someone else stuck with you?"}, {"id": "f2", "type": "textarea", "label": "What was it like to wait for the music to stop?"}, {"id": "f3", "type": "textarea", "label": "If you wrote a prompt for the next parcel, what would it be?"}, {"id": "f4", "type": "textarea", "label": "What did the group do with the prize at the end?"}]'::jsonb, array['group', 'connection', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('hot-and-cold-hidden-object-grounding-game', 'Hot and Cold Hidden Object Grounding Game', 'game'::resource_kind, 'A pairs game where one player hides an object and guides the other with hot and cold, then both describe the object with their senses.', 'Use it to practice attention and grounding through a seeking game that ends in a sensory description.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'In pairs, one player hides a small object in the room while the other closes their eyes. The seeker moves and the hider calls hot, warm, cold or freezing. When the object is found, the seeker holds it and describes five things about it through the senses before the pair swaps roles. Two rounds each, then debrief what it was like to search with only hot and cold for a map. Watch for a seeker who gives up quickly; shrink the search area rather than giving hints.', '[{"id": "f0", "type": "textarea", "label": "What did you hide, and where?"}, {"id": "f1", "type": "textarea", "label": "How did it feel to search with only hot and cold to guide you?"}, {"id": "f2", "type": "textarea", "label": "Five things you noticed about the object through your senses when you found it:"}, {"id": "f3", "type": "textarea", "label": "Was it easier to be the hider or the seeker? Why?"}, {"id": "f4", "type": "textarea", "label": "Where in your day could you use five senses noticing the way you did here?"}]'::jsonb, array['group', 'grounding', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('who-am-i-sticky-note-forehead-strengths-game', 'Who Am I Sticky Note Forehead Strengths Game', 'game'::resource_kind, 'A group game where each player wears a strength on their forehead that others wrote, and guesses it from yes-or-no questions.', 'Use it to let a group give each other strengths indirectly and practice receiving them.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each player writes one strength they have seen in the player to their left on a sticky note and puts it on that player''s forehead without showing them. Players then take turns asking the group yes-or-no questions to guess their own strength, with three questions per turn. When they guess it, the writer gives one example of when they saw it. Debrief what it was like to have the group confirm the strength. Watch for players who guess only modest strengths; ask them what the group''s answers suggest.', '[{"id": "f0", "type": "textarea", "label": "What strength did the group put on your forehead?"}, {"id": "f1", "type": "textarea", "label": "Which questions helped you guess it?"}, {"id": "f2", "type": "textarea", "label": "What example did the writer give of seeing it in you?"}, {"id": "f3", "type": "textarea", "label": "What strength did you write for the person on your left, and why?"}, {"id": "f4", "type": "textarea", "label": "What was it like to have the group confirm your strength?"}]'::jsonb, array['group', 'strengths', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('telling-a-new-partner-the-headline-not-the-story-sheet', 'Telling a New Partner the Headline Not the Story Sheet', 'worksheet'::resource_kind, 'A planning sheet for a client deciding what a new partner needs to know about their past, in a headline sentence, without the details.', 'Use it to help a client share enough with a new partner to be supported, at a pace they control, without reliving anything.', array['Adults']::text[], '30 minutes in session', 'Clients often believe disclosure means telling everything or nothing. The sheet separates the headline, one or two sentences that name that something hard happened and how it shows up now, from the story, which stays theirs. They plan when and where, what reaction they hope for, what they will do if the reaction is clumsy, and how they will end the conversation. Complete it in session, not as homework, and do not ask for any detail of what happened. Watch for a client who plans the headline to test the partner rather than to be supported.', '[{"id": "f0", "type": "textarea", "label": "My headline: one or two sentences that say something hard happened and how it shows up for me now:"}, {"id": "f1", "type": "textarea", "label": "What I want my partner to do with it: how to be with me, and what not to do:"}, {"id": "f2", "type": "textarea", "label": "When and where I would feel steadiest saying it:"}, {"id": "f3", "type": "textarea", "label": "What I will say if the reaction is clumsy or they ask for details I am not ready to give:"}, {"id": "f4", "type": "textarea", "label": "How I will close the conversation and look after myself afterward:"}, {"id": "f5", "type": "textarea", "label": "What I would need to see over time to share more, if I choose to:"}]'::jsonb, array['PTSD and trauma', 'safety', 'pacing', 'relationships']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('feeling-unsafe-versus-being-unsafe-two-column-sheet', 'Feeling Unsafe Versus Being Unsafe Two-Column Sheet', 'cbt'::resource_kind, 'A two-column sheet for moments of alarm that separates the felt sense of danger from the evidence about present danger.', 'Use it to help a client whose alarm fires often tell the two apart without dismissing the feeling.', array['Adults', 'Teens']::text[], '15 minutes, repeated after alarm moments', 'After a moment of alarm, the client writes what the feeling of unsafety was like and how strong it was, then, in the second column, what they can observe about present safety: who is here, where the exits are, what is actually happening. The feeling is never argued with; it is logged next to the facts. Over weeks the sheet shows how often the two columns disagree. Watch for a client who uses the facts column to shame themselves for feeling alarmed; the alarm made sense once.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what set the alarm off, in a few words:"}, {"id": "f1", "type": "textarea", "label": "The feeling of being unsafe: how strong, zero to one hundred, and what it did in my body:"}, {"id": "f2", "type": "textarea", "label": "What I can observe about the present moment: who is here, what is happening, where the exits are:"}, {"id": "f3", "type": "textarea", "label": "How the two columns compare today:"}, {"id": "f4", "type": "textarea", "label": "One thing I did to care for the alarm, even though the present was safe:"}, {"id": "f5", "type": "textarea", "label": "What I notice across several of these sheets:"}]'::jsonb, array['PTSD and trauma', 'safety', 'grounding', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('holding-the-memory-like-a-photo-not-a-window-page', 'Holding the Memory Like a Photo Not a Window Page', 'act'::resource_kind, 'A defusion page comparing a hard memory to a photograph the client can hold at arm''s length, rather than a window they fall through.', 'Use it to give a client a stance toward intrusive memories that keeps them in the present without fighting the memory.', array['Adults']::text[], '20 minutes in session', 'When a memory arrives as a window, the client is back there; when it is a photo, they are here looking at something from then. The page practices noticing the moment the memory arrives, naming it as a photo, noticing the hand holding it and the room around it, and choosing where to put the photo down. The content of the memory is never written here. Complete it in session first. Watch for a client who hears photo as a demand to feel nothing; the photo can be painful to hold and still be a photo.', '[{"id": "f0", "type": "textarea", "label": "The words I will use when a memory arrives: this is a photo from then, and I am here now:"}, {"id": "f1", "type": "textarea", "label": "Three things in the room around me that are only here, now, not in the photo:"}, {"id": "f2", "type": "textarea", "label": "What my body does when I remember the photo is in my hand rather than around me:"}, {"id": "f3", "type": "textarea", "label": "Where I can set the photo down for now, and what I want to do next in the present:"}, {"id": "f4", "type": "textarea", "label": "One moment this week when a memory came as a window and I turned it into a photo:"}, {"id": "f5", "type": "textarea", "label": "Who I can tell about how the practice is going, so I am not doing it alone:"}]'::jsonb, array['PTSD and trauma', 'defusion', 'grounding', 'stabilizing']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-weighted-blanket-wind-down-card', 'Paced Breathing and Weighted Blanket Wind-Down Card', 'dbt'::resource_kind, 'A self-soothe card pairing paced breathing with a weighted blanket or heavy quilt for the hour before sleep after a hard day.', 'Use it to give a client whose body stays on alert at night a wind-down they can do with no skill beyond breathing and weight.', array['Adults', 'Teens']::text[], '15 minutes nightly', 'The card sets a simple sequence: lights low, blanket on, paced breathing at the client''s own count for ten minutes, then a short five-senses check of the room. The weight gives the body something to feel that is not alarm. Have the client try it on a calm night first. Watch for a client for whom weight on the body is itself a reminder; swap the blanket for a warm drink held in both hands and keep the rest of the sequence.', '[{"id": "f0", "type": "textarea", "label": "My wind-down sequence, step by step, in the order I will do it:"}, {"id": "f1", "type": "textarea", "label": "My paced breathing count, and where I feel the slowing:"}, {"id": "f2", "type": "textarea", "label": "Five things I notice in my room through my senses at the end:"}, {"id": "f3", "type": "textarea", "label": "Nights this week I used it, and how long it took my body to settle, roughly:"}, {"id": "f4", "type": "textarea", "label": "What I will change if any part of the sequence does not feel right:"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'sleep', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('secret-safe-signal-hand-sign-invention-play', 'Secret Safe Signal Hand Sign Invention Play', 'kids'::resource_kind, 'A play session where a child and parent invent a private hand sign that means I need you close, and practice using it in a game.', 'Use it to give a child who has been through something frightening a wordless way to call a safe adult over.', array['Children']::text[], '20 minutes', 'The child and parent invent a hand sign together, something small they can do across a room. The parent then plays a game: they move around the room pretending to be busy, the child flashes the sign, and the parent comes immediately and sits beside them without asking why. Repeat until it is automatic, then agree where else it works: school pickup, family gatherings. Nothing about what happened is asked for. If the child discloses anything during the play, follow your reporting duties. Watch for a parent who asks why each time; coming is the whole answer.', '[{"id": "f0", "type": "textarea", "label": "Draw your secret hand sign:"}, {"id": "f1", "type": "textarea", "label": "Who knows the sign, and who it is just for?"}, {"id": "f2", "type": "textarea", "label": "What does your grown-up do when they see the sign?"}, {"id": "f3", "type": "textarea", "label": "Where are some places you might use it?"}, {"id": "f4", "type": "textarea", "label": "How did it feel when your grown-up came over right away in the game?"}]'::jsonb, array['PTSD and trauma', 'children', 'safety', 'play']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('email-re-read-before-sending-count-log', 'Email Re-Read Before Sending Count Log', 'worksheet'::resource_kind, 'A log of how many times a client re-reads a message before sending, what they are checking for, and what happened after sending.', 'Use it to make a hidden anxious habit visible and set up a gradual reduction the client chooses.', array['Adults', 'Teens']::text[], 'One week', 'Re-reading an email or text before sending can swallow an hour a day while feeling like diligence. The client logs each message that took more than two reads, the count, what they were checking for, and the actual reply or outcome. At the end of the week they set a new maximum for ordinary messages. Watch for a client who re-reads after sending as well; add that to the log. The outcomes column usually shows that reread messages do no better than the ones sent quickly.', '[{"id": "f0", "type": "textarea", "label": "Each message that took more than two reads: who it was to, and how many reads:"}, {"id": "f1", "type": "textarea", "label": "What I was checking for each time:"}, {"id": "f2", "type": "textarea", "label": "How long the re-reading took, roughly:"}, {"id": "f3", "type": "textarea", "label": "What actually happened after I sent it: the reply, or nothing:"}, {"id": "f4", "type": "textarea", "label": "My new maximum number of reads for an ordinary message:"}, {"id": "f5", "type": "textarea", "label": "What I did with the first message I sent under the new maximum:"}]'::jsonb, array['anxiety', 'self-monitoring', 'safety behaviors', 'worry']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('if-i-relax-something-bad-will-happen-rule-test-sheet', 'If I Relax Something Bad Will Happen Rule Test Sheet', 'cbt'::resource_kind, 'A sheet that tests the rule that staying tense keeps bad things away, with a planned hour of letting go and what followed.', 'Use it to help a client who guards against disaster by never relaxing test what the guarding actually does.', array['Adults', 'Teens']::text[], 'One week', 'Many anxious clients hold a half-spoken rule that vigilance is protective and relaxing invites trouble. The sheet writes the rule out, finds the evidence the client uses for it, and then plans one hour of deliberate ease, with a prediction of what will go wrong and how. Afterward they record what did and did not happen. Repeat with longer windows. Watch for a client who says nothing went wrong because they were secretly still vigilant; ask what they did with their hands and attention.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words: if I relax, then…"}, {"id": "f1", "type": "textarea", "label": "The evidence I have been using for the rule:"}, {"id": "f2", "type": "textarea", "label": "The hour I will spend deliberately at ease this week, and what I will do with it:"}, {"id": "f3", "type": "textarea", "label": "My prediction: what will go wrong, how sure I am, and when it will show:"}, {"id": "f4", "type": "textarea", "label": "What actually happened during and in the day after:"}, {"id": "f5", "type": "textarea", "label": "What the rule looks like now, and the next longer test:"}]'::jsonb, array['anxiety', 'behavioral experiment', 'core beliefs', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('waiting-room-of-life-metaphor-page', 'Waiting Room of Life Metaphor Page', 'act'::resource_kind, 'A metaphor page for the client who is waiting to feel calm before living, picturing life as a waiting room they never leave.', 'Use it to help a client see what waiting for anxiety to pass has cost and choose one door to walk through now.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to picture a waiting room where their name will be called when the anxiety is gone, and list what they have put off until then. Then ask how long they have been sitting there. The page moves from the inventory to a single door they could walk through this week while still anxious, and what they would carry with them. Watch for a client who treats the metaphor as proof they have wasted their life; the point is the door, not the chair.', '[{"id": "f0", "type": "textarea", "label": "Things I have put off until I feel calmer:"}, {"id": "f1", "type": "textarea", "label": "How long I have been in the waiting room, roughly:"}, {"id": "f2", "type": "textarea", "label": "What I have told myself about when my name will be called:"}, {"id": "f3", "type": "textarea", "label": "One door I could walk through this week while still anxious:"}, {"id": "f4", "type": "textarea", "label": "What I will bring with me, from values to a support person:"}, {"id": "f5", "type": "textarea", "label": "What happened when I walked through it, anxiety and all:"}]'::jsonb, array['anxiety', 'willingness', 'metaphor', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-parent-teacher-conference-card', 'Cope Ahead for the Parent-Teacher Conference Card', 'dbt'::resource_kind, 'A cope ahead card for a parent dreading a school conference, rehearsing the hard moment and the skill they will use.', 'Use it to help an anxious parent walk into a conference with a rehearsed plan instead of a week of dread.', array['Adults']::text[], '20 minutes to plan, used once', 'The client describes the conference moment they fear most, usually hearing something critical about their child, names the emotion it will bring, and chooses the skill: a question they will ask, a breath, a phrase for buying time. Then they rehearse it in imagination with the feeling present, twice. Watch for a parent who rehearses a perfect calm; the rehearsal should include the flush and the lump in the throat and still arrive at the skill.', '[{"id": "f0", "type": "textarea", "label": "The moment in the conference I am dreading, as specifically as I can picture it:"}, {"id": "f1", "type": "textarea", "label": "The emotion it will bring, and where I will feel it:"}, {"id": "f2", "type": "textarea", "label": "The skill I will use in that moment, exactly:"}, {"id": "f3", "type": "textarea", "label": "The question I will ask the teacher that keeps me in the conversation:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I rehearsed it in my mind with the feeling present:"}, {"id": "f5", "type": "textarea", "label": "How it actually went, and what I would keep for next time:"}]'::jsonb, array['anxiety', 'cope ahead', 'parenting', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('probability-line-stand-where-you-guess-game', 'Probability Line Stand Where You Guess Game', 'game'::resource_kind, 'A group game where players stand along a zero to one hundred floor line to show how likely each feared event is, then compare.', 'Use it to let a group see how estimates of the same event vary, and to feel their own estimate move during discussion.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Tape a line across the floor marked zero at one end and one hundred at the other. The facilitator reads a feared event from a prepared stack, written in plain terms, and every player stands at the number they believe. Players at the extremes explain their position in one sentence each; then everyone may move once. Five or six events, then debrief what moved people. Watch for events that are too personal for the group; keep the stack to shared everyday fears like a flight being canceled.', '[{"id": "f0", "type": "textarea", "label": "Which feared event did you have the strongest reaction to, and where did you stand?"}, {"id": "f1", "type": "textarea", "label": "Where did most of the group stand compared with you?"}, {"id": "f2", "type": "textarea", "label": "What did someone say that made you move, if you moved?"}, {"id": "f3", "type": "textarea", "label": "Which event had the widest spread across the room, and why do you think that is?"}, {"id": "f4", "type": "textarea", "label": "One feared event from your own life you would like to put on the line:"}]'::jsonb, array['anxiety', 'probability', 'group', 'game']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('front-door-crossings-tally-sheet', 'Front Door Crossings Tally Sheet', 'worksheet'::resource_kind, 'A simple tally of every time a client crosses their front door going out, with the reason and how they felt an hour later.', 'Use it to give a client who has stopped leaving the house one small countable behavior to notice and grow.', array['Adults', 'Teens']::text[], 'One week', 'For a client whose world has shrunk to their home, the number of times they cross the front door is a plain measure that neither of you has to interpret. They tally each crossing, the reason, how long they were out and how they felt an hour afterward. The second week they set a target one higher than the first. Watch for a client who counts only purposeful trips; a step onto the porch for air counts, and often it is the first one.', '[{"id": "f0", "type": "textarea", "label": "Each time I went out this week: the day, the reason and how long I was gone:"}, {"id": "f1", "type": "textarea", "label": "How I felt an hour after each time I came back, compared with before I left:"}, {"id": "f2", "type": "textarea", "label": "My total crossings for the week:"}, {"id": "f3", "type": "textarea", "label": "The crossing that felt hardest to start, and what got me over the step:"}, {"id": "f4", "type": "textarea", "label": "My target for next week, one higher than this week:"}, {"id": "f5", "type": "textarea", "label": "One reason to cross that I could add, even for two minutes:"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('they-only-invite-me-out-of-pity-thought-record', 'They Only Invite Me Out of Pity Thought Record', 'cbt'::resource_kind, 'A thought record for the belief that invitations are pity rather than wanting, with the evidence weighed and a test planned.', 'Use it to catch the thought that turns a kind invitation into proof of being a burden.', array['Adults', 'Teens']::text[], '20 minutes', 'An invitation arrives and the client hears obligation. The record captures the invitation, the pity thought and how much they believe it, then the evidence on both sides: how the person acted when they came, whether invitations continued after a decline, what pity would actually look like. It ends with a test, usually accepting once and watching for the signs of pity they predicted. Watch for a client who declines to protect the other person from having to pretend; that is the thought acting.', '[{"id": "f0", "type": "textarea", "label": "The invitation, who it came from and the exact words:"}, {"id": "f1", "type": "textarea", "label": "The thought about why they invited me, and how much I believe it, zero to one hundred:"}, {"id": "f2", "type": "textarea", "label": "What pity would actually look like in how they behave if I went:"}, {"id": "f3", "type": "textarea", "label": "Evidence they want my company, including how past times together went:"}, {"id": "f4", "type": "textarea", "label": "Evidence it is pity, held to the same standard:"}, {"id": "f5", "type": "textarea", "label": "My test: what I will do, and what I will watch for:"}]'::jsonb, array['depression', 'thought record', 'core CBT', 'relationships']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('half-power-still-counts-committed-action-page', 'Half Power Still Counts Committed Action Page', 'act'::resource_kind, 'A committed action page for low-energy weeks that plans valued actions at half power and counts them in full.', 'Use it to help a client who stops acting when they cannot act well keep moving in a valued direction at any power level.', array['Adults', 'Teens']::text[], '20 minutes, one week to use', 'Depressed clients often rule that an action done at half power does not count, so they do nothing. The page takes three valued actions and writes the full-power version and the half-power version of each, then plans the half-power versions for the week. Every completed half-power action counts whole. Watch for a client who completes a half-power version and immediately discounts it; the page asks them to record it before the mind gets a vote.', '[{"id": "f0", "type": "textarea", "label": "Three actions that matter to me that I have stopped because I cannot do them properly:"}, {"id": "f1", "type": "textarea", "label": "The full-power version of each, as I imagine it should look:"}, {"id": "f2", "type": "textarea", "label": "The half-power version of each: shorter, smaller, imperfect, still pointed the same way:"}, {"id": "f3", "type": "textarea", "label": "The half-power actions I will do this week, and when:"}, {"id": "f4", "type": "textarea", "label": "What I completed, recorded before my mind could discount it:"}, {"id": "f5", "type": "textarea", "label": "What half power gave me that doing nothing did not:"}]'::jsonb, array['depression', 'committed action', 'values', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('describe-the-day-without-the-verdict-card', 'Describe the Day Without the Verdict Card', 'dbt'::resource_kind, 'A mindfulness card for the end of a low day that describes what happened in plain facts and leaves out the verdict on the day and the self.', 'Use it to help a client separate the events of a hard day from the global judgment that follows at bedtime.', array['Adults', 'Teens']::text[], 'Ten minutes nightly for a week', 'At bedtime, the depressed mind delivers a verdict: wasted, useless, same as always. The card asks the client to write what happened in observable terms only, from waking to now, and then to notice each verdict word that tries to get in and set it aside. The description is often longer and more varied than the verdict. Watch for a client who describes only what they did not do; absence is a judgment in disguise, so ask what they did do with those hours.', '[{"id": "f0", "type": "textarea", "label": "What I did today, in order, in plain facts, including small things like making tea or answering a message:"}, {"id": "f1", "type": "textarea", "label": "Verdict words that tried to get into the description, which I set aside:"}, {"id": "f2", "type": "textarea", "label": "How long the description is compared with the verdict I usually give:"}, {"id": "f3", "type": "textarea", "label": "One fact from the description I would have missed if I had only kept the verdict:"}, {"id": "f4", "type": "textarea", "label": "What I notice about my mood after describing versus after judging:"}]'::jsonb, array['depression', 'mindfulness', 'core DBT', 'self-criticism']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('couch-dates-for-low-weeks-menu-for-partners', 'Couch Dates for Low Weeks Menu for Partners', 'couples'::resource_kind, 'A menu of low-energy ways for partners to spend time together when one of them is in a low stretch, agreed in advance.', 'Use it to keep a couple connected through a low period without plans that one partner cannot manage.', array['Couples']::text[], '30 minutes to build, used during low weeks', 'When one partner is low, dates stop and both feel the distance. Together they build a menu of ten things they can do side by side with almost no energy: a show with the phones away, a shared playlist, a walk to the mailbox. The low partner marks what feels possible on a bad day; the other marks what feels like real connection to them. The overlap is the menu. Watch for the well partner''s quiet grief at the smaller dates, which deserves its own space.', '[{"id": "f0", "type": "textarea", "label": "Partner who is low: ten things we could do together that would ask almost nothing of me:"}, {"id": "f1", "type": "textarea", "label": "Partner who is not: which of those would feel like real time together to me:"}, {"id": "f2", "type": "textarea", "label": "Our couch date menu: the ones we both marked:"}, {"id": "f3", "type": "textarea", "label": "What each of us will say to start one, so it does not need planning:"}, {"id": "f4", "type": "textarea", "label": "What we each want the other to know about how the low weeks feel:"}, {"id": "f5", "type": "textarea", "label": "The couch dates we had this week, and one small thing that was good about one of them:"}]'::jsonb, array['depression', 'couples', 'connection', 'support']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('half-finished-projects-decision-sheet', 'Half-Finished Projects Decision Sheet', 'worksheet'::resource_kind, 'A sheet that lists every abandoned project, from a craft to a course, and decides for each: finish, shrink, or let go on purpose.', 'Use it to help a client whose home is full of half-finished things turn a pile of guilt into a set of decisions.', array['Adults', 'Teens']::text[], '40 minutes', 'Each unfinished project is a small reproach every time the client sees it. The sheet has them list all of them, mark what finishing each would actually take, what it was for in the first place, and then decide: finish with a date, shrink to a smaller done, or let go deliberately, which includes physically clearing it away. Watch for a client who marks everything finish; limit that column to two and ask which project they would start again today if it did not exist.', '[{"id": "f0", "type": "textarea", "label": "Every half-finished project I can think of, around the house and online:"}, {"id": "f1", "type": "textarea", "label": "For each: what it was for when I started it:"}, {"id": "f2", "type": "textarea", "label": "For each: honestly, what finishing it would take in hours and materials:"}, {"id": "f3", "type": "textarea", "label": "The two I will finish, with a date and a first step:"}, {"id": "f4", "type": "textarea", "label": "The ones I will shrink to a smaller version of done, and what that version is:"}, {"id": "f5", "type": "textarea", "label": "The ones I will let go on purpose, and how I will clear them away this week:"}]'::jsonb, array['ADHD', 'decisions', 'executive function', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('one-mistake-means-i-am-careless-labeling-check-sheet', 'One Mistake Means I Am Careless Labeling Check Sheet', 'cbt'::resource_kind, 'A sheet that catches the jump from a single slip to a character label, and replaces the label with a description and a fix.', 'Use it to help a client who collects every forgotten item as proof of a flaw describe the slip instead.', array['Adults', 'Teens']::text[], '15 minutes, repeated after slips', 'A missed email or a lost key becomes I am careless within seconds. The sheet records the slip in plain terms, the label that followed, the evidence of the opposite from the same week, and a description of what happened in terms of attention, systems and timing. It ends with one adjustment to the system, not to the self. Watch for a client who turns the system fix into another label about needing systems; a reminder is a tool, not a confession.', '[{"id": "f0", "type": "textarea", "label": "The slip, in plain terms: what, when, and what it cost:"}, {"id": "f1", "type": "textarea", "label": "The label my mind attached to me, and how fast it arrived:"}, {"id": "f2", "type": "textarea", "label": "Three things from the same week that do not fit the label:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, described in terms of attention, timing and the system I was using:"}, {"id": "f4", "type": "textarea", "label": "One adjustment to the system, not to my character:"}, {"id": "f5", "type": "textarea", "label": "The sentence I will use the next time a slip happens:"}]'::jsonb, array['ADHD', 'thinking traps', 'core CBT', 'self-criticism']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('hyperfocus-hours-values-check-page', 'Hyperfocus Hours Values Check Page', 'act'::resource_kind, 'A page that reviews where the client''s hyperfocus hours went this week and checks them against what they say matters most.', 'Use it to help a client aim a powerful capacity at what they value rather than at whatever caught it first.', array['Adults', 'Teens']::text[], '20 minutes weekly', 'Hyperfocus is not the problem; where it lands is the question. The page lists the stretches of deep absorption this week, what each was spent on and what it displaced, then sets them beside the client''s top values. The client plans one way to make a valued task more likely to catch the focus next week, such as starting it when the pull is strongest. Watch for a client who shames themselves for the absorbing hours; many of them were good, and the page should say so.', '[{"id": "f0", "type": "textarea", "label": "The stretches of deep focus I had this week, and what each was on:"}, {"id": "f1", "type": "textarea", "label": "What each stretch pushed aside, if anything:"}, {"id": "f2", "type": "textarea", "label": "My top three values, in my own words:"}, {"id": "f3", "type": "textarea", "label": "Which focus stretches lined up with those values, and which did not:"}, {"id": "f4", "type": "textarea", "label": "One valued task I will set up to catch the focus next week, and how:"}, {"id": "f5", "type": "textarea", "label": "A focus stretch this week that was simply good, with nothing to fix:"}]'::jsonb, array['ADHD', 'values', 'core ACT', 'attention']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('dear-man-for-asking-for-written-instructions-card', 'DEAR MAN for Asking for Written Instructions Card', 'dbt'::resource_kind, 'A DEAR MAN card for asking a manager or teacher to put instructions in writing, scripted and rehearsed.', 'Use it to help a client who loses verbal instructions ask for what they need without apology.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients who lose spoken instructions often cover rather than ask, and then get the work wrong. The card scripts the ask: describe the situation, express how it affects the work, assert the request for written steps or a follow-up message, reinforce the benefit to the other person, then mindful, appear confident, negotiate a fallback such as a quick recap at the end of the meeting. Rehearse it aloud. Watch for an ask buried in apology; strike every sorry from the script.', '[{"id": "f0", "type": "textarea", "label": "Describe: the situations where I get instructions out loud and lose them:"}, {"id": "f1", "type": "textarea", "label": "Express: how that affects the work, in one sentence without apology:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking for, in writing or by message:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the other person gets from it:"}, {"id": "f4", "type": "textarea", "label": "Negotiate: my fallback if they say no to the full request:"}, {"id": "f5", "type": "textarea", "label": "How the ask went, and what I got:"}]'::jsonb, array['ADHD', 'DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('finished-jobs-drop-box-craft', 'Finished Jobs Drop Box Craft', 'kids'::resource_kind, 'A craft that makes a decorated drop box where a child posts a card for each finished job, and a parent-run weekly reveal.', 'Use it to give a child who starts many things and finishes few a physical place where finishing is seen and celebrated.', array['Children']::text[], '30 minutes to make, one week to use', 'The child decorates a shoebox with a slot and makes a stack of small cards. Each time they finish a job, from putting away shoes to the last page of a reader, they write or draw it on a card and post it. The parent does not police what counts; the child decides. At the end of the week the parent opens the box with ceremony and reads each card aloud. Watch for a parent who adds should-have cards; the box is for what got done.', '[{"id": "f0", "type": "textarea", "label": "Draw how you decorated your drop box:"}, {"id": "f1", "type": "textarea", "label": "What was the first finished job you posted?"}, {"id": "f2", "type": "textarea", "label": "Which finished job are you proudest of this week?"}, {"id": "f3", "type": "textarea", "label": "What did it feel like when your grown-up read the cards out loud?"}, {"id": "f4", "type": "textarea", "label": "What job do you want to finish and post next week?"}]'::jsonb, array['ADHD', 'children', 'craft', 'task initiation']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('phone-contacts-cleanup-sheet-for-early-recovery', 'Phone Contacts Cleanup Sheet for Early Recovery', 'worksheet'::resource_kind, 'A sheet for going through the phone and deciding, contact by contact, who is tied to substance use and what happens to their number.', 'Use it to help a client in early recovery clear the easiest route back to using before an urge makes the call.', array['Adults', 'Teens']::text[], '45 minutes, in session or with a support person', 'The phone holds the quickest path to using again. The client sorts contacts into delete, block, keep with a plan, and keep as support, and writes what each tie means to them, because some of these people were friends. For the keep with a plan group they write what they will say if the person reaches out. Do this with a support person present if the client wants that. Watch for grief about the deletions, which is real and belongs in the room, and for the contact kept just in case.', '[{"id": "f0", "type": "textarea", "label": "Contacts tied to substance use, sorted into delete, block, keep with a plan, keep as support:"}, {"id": "f1", "type": "textarea", "label": "For the ones I am deleting or blocking: what this person meant to me, honestly:"}, {"id": "f2", "type": "textarea", "label": "For the keep with a plan group: what I will say if they reach out:"}, {"id": "f3", "type": "textarea", "label": "Group chats and apps that need the same sorting:"}, {"id": "f4", "type": "textarea", "label": "Who I will have beside me while I do it, and when:"}, {"id": "f5", "type": "textarea", "label": "How I felt an hour after the cleanup, and what urges came up:"}]'::jsonb, array['addiction', 'substance use', 'relapse prevention', 'safety']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('i-deserve-it-after-a-hard-day-permission-thought-record', 'I Deserve It After a Hard Day Permission Thought Record', 'cbt'::resource_kind, 'A thought record for the permission-giving thought that frames substance use as a reward earned by a hard day.', 'Use it to help a client catch the reward thought early and test what the reward actually delivers.', array['Adults']::text[], '15 minutes, repeated after hard days', 'The thought arrives dressed as fairness: it was hard, so I have earned it. The record captures the day, the exact permission thought and the belief rating, then asks what the use actually delivered last time, how the next morning went, and what else would answer the real need, which is usually rest or relief. It ends with a reward that does not cost tomorrow. Watch for a client who agrees in session and reports the thought won anyway; shorten the record to three lines they can do in the moment.', '[{"id": "f0", "type": "textarea", "label": "What made today hard, in a few words:"}, {"id": "f1", "type": "textarea", "label": "The permission thought, word for word, and how much I believed it:"}, {"id": "f2", "type": "textarea", "label": "What I was actually needing underneath the thought: rest, relief, company, quiet:"}, {"id": "f3", "type": "textarea", "label": "What using delivered last time, including the next morning:"}, {"id": "f4", "type": "textarea", "label": "A reward that answers the need and does not cost tomorrow:"}, {"id": "f5", "type": "textarea", "label": "What I did tonight, and how I feel about it:"}]'::jsonb, array['addiction', 'substance use', 'thought record', 'urges']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('the-minds-bargaining-table-defusion-page', 'The Mind''s Bargaining Table Defusion Page', 'act'::resource_kind, 'A defusion page that names the mind''s bargains around substance use, just one, only tonight, as offers on a table the client can decline.', 'Use it to help a client hear the bargaining voice as bargaining rather than as a decision already made.', array['Adults', 'Teens']::text[], '20 minutes', 'Urges often arrive as negotiations. The page has the client write every bargain their mind has offered, what each one actually cost when accepted before, and then practice a stance: seeing the offer on the table, naming it as a bargain, and leaving the table for a valued action. Watch for a client who counters the bargain with arguments; that is still sitting at the table, and the mind is a better negotiator.', '[{"id": "f0", "type": "textarea", "label": "The bargains my mind offers around substance use, in its own words:"}, {"id": "f1", "type": "textarea", "label": "What each bargain actually cost the last time I took it:"}, {"id": "f2", "type": "textarea", "label": "The words I will use when I see a bargain on the table: that is a bargain, not a decision:"}, {"id": "f3", "type": "textarea", "label": "What I will walk toward when I leave the table:"}, {"id": "f4", "type": "textarea", "label": "One time this week I left the table, and what the mind did next:"}, {"id": "f5", "type": "textarea", "label": "Who I can tell about the bargains so they are not a secret:"}]'::jsonb, array['addiction', 'defusion', 'urges', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-wedding-open-bar-card', 'Cope Ahead for the Wedding Open Bar Card', 'dbt'::resource_kind, 'A cope ahead card for a wedding or big celebration with an open bar, rehearsing the hard moments and the skills in advance.', 'Use it to help a client in recovery arrive at a celebration with the moments planned rather than improvised.', array['Adults']::text[], '25 minutes to plan, used once', 'Weddings bundle several hard moments: the toast, the table of old friends, the hour when everyone is loose. The card has the client name the three moments they expect to be hardest, the urge each will bring, the exact skill for each, who their person at the event is, and the leaving plan. Then they rehearse each moment in imagination with the urge present. Watch for a client who plans to white-knuckle it; a plan that includes leaving early is a strength.', '[{"id": "f0", "type": "textarea", "label": "The three moments at this event I expect to be hardest:"}, {"id": "f1", "type": "textarea", "label": "The urge each moment will bring, and how strong I expect it to be:"}, {"id": "f2", "type": "textarea", "label": "The skill I will use in each moment, exactly:"}, {"id": "f3", "type": "textarea", "label": "My person at the event, and what I have told them:"}, {"id": "f4", "type": "textarea", "label": "My leaving plan: the time, the ride, and what I will say:"}, {"id": "f5", "type": "textarea", "label": "How it went, and what I would keep for the next celebration:"}]'::jsonb, array['addiction', 'cope ahead', 'urges', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('your-drinking-around-my-recovery-talk-sheet-for-partners', 'Your Drinking Around My Recovery Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for a couple where one partner is in recovery and the other still drinks, naming what each needs at home and out.', 'Use it to help partners agree how substances are handled in a shared life without one partner feeling policed or the other unsafe.', array['Couples']::text[], '45 minutes', 'The partner in recovery writes what the other''s drinking is like for them at home, at parties and after a hard day, and what would make each setting easier. The other partner writes what they fear losing, what feels like being controlled, and what they are willing to change. They agree on what is in the house, what happens at events, and a signal for when one of them needs to go. Watch for the recovering partner apologizing for having needs, and for the other hearing every request as blame.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what your drinking is like for me at home, at events and on hard days:"}, {"id": "f1", "type": "textarea", "label": "Partner who drinks: what I fear losing, and what feels like being controlled:"}, {"id": "f2", "type": "textarea", "label": "What each of us is willing to change, and what we are not:"}, {"id": "f3", "type": "textarea", "label": "Our agreement about what is in the house and what happens at events:"}, {"id": "f4", "type": "textarea", "label": "Our signal for when either of us needs to leave or needs the other to stop:"}, {"id": "f5", "type": "textarea", "label": "How we will check this agreement in a month, without a fight:"}]'::jsonb, array['addiction', 'couples', 'substance use', 'boundaries']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('angry-email-drafts-folder-overnight-rule-sheet', 'Angry Email Drafts Folder Overnight Rule Sheet', 'worksheet'::resource_kind, 'A sheet that sets up a drafts folder rule for angry messages, with a log of what was drafted at night and what survived the morning.', 'Use it to give a client who sends heated messages a built-in delay and the evidence of what the delay saves.', array['Adults', 'Teens']::text[], 'Two weeks', 'The rule is simple: any message written while angry goes to drafts until the next morning. The sheet logs each draft, the anger level when written, and the morning decision: send as is, edit, or delete. Over two weeks the delete column makes its own case. Watch for a client who moves the anger to a different channel, such as a text or a call, after drafting; the rule covers all of them.', '[{"id": "f0", "type": "textarea", "label": "Each angry message I drafted: who it was to, and my anger level when I wrote it:"}, {"id": "f1", "type": "textarea", "label": "What I did with each the next morning: sent as written, edited, or deleted:"}, {"id": "f2", "type": "textarea", "label": "For the ones I edited: what changed:"}, {"id": "f3", "type": "textarea", "label": "For the ones I deleted: what I think would have happened if I had sent them:"}, {"id": "f4", "type": "textarea", "label": "Any time I went around the rule with a text or a call, and what followed:"}, {"id": "f5", "type": "textarea", "label": "What the two-week tally shows me:"}]'::jsonb, array['anger management', 'de-escalation', 'communication', 'self-monitoring']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('unfairness-ledger-balance-check-sheet', 'Unfairness Ledger Balance Check Sheet', 'cbt'::resource_kind, 'A sheet that logs the unfair events that fuel the client''s anger alongside the fair and generous ones the mind files away.', 'Use it to show a client how a one-sided ledger keeps anger running and to practice keeping both columns.', array['Adults', 'Teens']::text[], 'One week', 'Angry clients keep a precise record of what was unfair and no record of what was fair. For a week the client logs both: every unfair event with its heat rating, and every time someone was fair, kind or generous to them, however small. At the end they compare the lengths of the two columns and how much attention each got. Watch for a client who dismisses the fair column as what people are supposed to do; ask whether the unfair column gets the same discount.', '[{"id": "f0", "type": "textarea", "label": "Unfair things that happened to me this week, with how hot each made me, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "Fair, kind or generous things that happened to me this week, however small:"}, {"id": "f2", "type": "textarea", "label": "Which column I noticed first each day, and which I thought about more:"}, {"id": "f3", "type": "textarea", "label": "How the two columns compare in length at the end of the week:"}, {"id": "f4", "type": "textarea", "label": "What my anger would be like if I kept both columns every week:"}, {"id": "f5", "type": "textarea", "label": "One fair thing I will look for tomorrow on purpose:"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT', 'fairness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('anger-as-an-overworked-bodyguard-page', 'Anger as an Overworked Bodyguard Page', 'act'::resource_kind, 'A metaphor page that casts anger as a bodyguard who protected the client once and now tackles everyone, including friends.', 'Use it to help a client appreciate what anger has done for them and renegotiate its job without trying to fire it.', array['Adults', 'Teens']::text[], '25 minutes', 'Anger often started as protection and has since lost its judgment about threats. The page has the client write what the bodyguard protected them from early on, who it has tackled lately who was not a threat, and what the bodyguard is really afraid of. Then the client writes new instructions for the bodyguard: stand close, speak first, tackle only on the client''s word. Watch for a client who wants to fire the bodyguard; anger that is dismissed usually comes back off duty.', '[{"id": "f0", "type": "textarea", "label": "What my anger protected me from when I first needed it:"}, {"id": "f1", "type": "textarea", "label": "People my bodyguard has tackled lately who were not actually a threat:"}, {"id": "f2", "type": "textarea", "label": "What the bodyguard seems to be afraid of underneath:"}, {"id": "f3", "type": "textarea", "label": "What I want to thank the bodyguard for, honestly:"}, {"id": "f4", "type": "textarea", "label": "The new instructions I am giving it, in plain words:"}, {"id": "f5", "type": "textarea", "label": "A moment this week the bodyguard stood close but waited for my word:"}]'::jsonb, array['anger management', 'metaphor', 'core ACT', 'willingness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('willing-hands-during-a-disagreement-card', 'Willing Hands During a Disagreement Card', 'dbt'::resource_kind, 'A card for using willing hands, palms open and relaxed, through a disagreement, with what the client noticed in their body and tone.', 'Use it to give a client a physical anchor for staying open while disagreeing, practiced in low-stakes arguments first.', array['Adults', 'Teens']::text[], 'Ten minutes to learn, used during disagreements', 'Clenched fists and crossed arms tell the body it is fighting. The card has the client practice willing hands while sitting through a mild disagreement, palms up on the knees or open at the sides, and notice what changes in their voice and in the other person. Start with low-stakes disagreements, such as which show to watch. Watch for a client who performs the hands while the jaw stays clenched; add a half smile and ask them to notice the jaw.', '[{"id": "f0", "type": "textarea", "label": "The disagreement I practiced in, and how heated it was, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "Where my hands were, and what it took to keep them open:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my voice and my words with my hands open:"}, {"id": "f3", "type": "textarea", "label": "What the other person did differently, if anything:"}, {"id": "f4", "type": "textarea", "label": "Where else in my body I was still clenched, and what I will add next time:"}]'::jsonb, array['anger management', 'core DBT', 'de-escalation', 'regulation']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('short-fuse-long-fuse-scenario-sort-game', 'Short Fuse Long Fuse Scenario Sort Game', 'game'::resource_kind, 'A group game where players sort everyday provocation cards onto a fuse line by how fast each would set them off, then compare and defend.', 'Use it to let a group see how differently the same provocation lands and find where each person''s fuse is shortest.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Lay a long paper fuse on the floor, lit end at one side. Deal each player five provocation cards: being cut off in traffic, a text left on read, a sibling borrowing without asking. In turn, each player places a card on the fuse where it belongs for them, from instant spark to barely warm, and says one sentence why. Others may ask one question. After every card is down, the group looks at where the cards cluster. Debrief where each person''s fuse is shortest and what that spot has in common. Watch for teasing about short fuses; the rule is curiosity, not comparison.', '[{"id": "f0", "type": "textarea", "label": "Which of your cards did you put closest to the lit end, and why?"}, {"id": "f1", "type": "textarea", "label": "Which card surprised you by where someone else placed it?"}, {"id": "f2", "type": "textarea", "label": "What do your short-fuse cards have in common?"}, {"id": "f3", "type": "textarea", "label": "What question did someone ask you that made you think?"}, {"id": "f4", "type": "textarea", "label": "One short-fuse situation you want to work on, and the first thing you would try:"}]'::jsonb, array['anger management', 'group', 'game', 'triggers']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('prayer-repetition-count-and-delay-sheet', 'Prayer Repetition Count and Delay Sheet', 'worksheet'::resource_kind, 'A log for a client whose prayers or religious phrases must be repeated until they feel right, counting repeats and practicing a delay.', 'Use it to help a client of faith separate their practice from the repetition the doubt demands, with respect for both.', array['Adults', 'Teens']::text[], 'One week', 'Scrupulous repetition can turn a comfort into a trap. Without touching the content of the client''s beliefs, the sheet counts how many times a prayer or phrase was repeated before it felt right, what the not-right feeling was like, and sets a small delay before the next repeat. Many clients find it helps to involve a trusted faith leader; ask whether they want to. Watch for the client who hears the sheet as a challenge to their faith; say plainly that the target is the doubt, not the prayer.', '[{"id": "f0", "type": "textarea", "label": "The prayer or phrase, and how many times I repeated it today before it felt right:"}, {"id": "f1", "type": "textarea", "label": "What the not-right feeling was like, and where I felt it:"}, {"id": "f2", "type": "textarea", "label": "The delay I practiced before repeating, and what happened to the feeling during the delay:"}, {"id": "f3", "type": "textarea", "label": "What my faith tradition actually says about getting the words right, as far as I know:"}, {"id": "f4", "type": "textarea", "label": "Whether I want to involve a faith leader I trust, and what I would ask them:"}, {"id": "f5", "type": "textarea", "label": "What changed in the count across the week:"}]'::jsonb, array['OCD', 'rituals', 'self-monitoring', 'intrusive thoughts']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('bad-thought-means-bad-person-belief-check-sheet', 'Bad Thought Means Bad Person Belief Check Sheet', 'cbt'::resource_kind, 'A sheet that tests the belief that having an intrusive thought reveals character, with a survey of how thoughts work and a fairness check.', 'Use it to loosen the moral weight a client gives to unwanted thoughts without debating the thoughts themselves.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes the belief in their own words and how much they hold it, then considers how thoughts arrive, what a thought and an action have in common, and whether they would judge a friend by a thought the friend did not want. The sheet never asks for the content of the thought in detail; a category is enough. It ends with a fairer sentence about what a thought means. Watch for a client who seeks reassurance that they are good; redirect to the fairness check rather than supplying the verdict.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words: having this kind of thought means I am…"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now, zero to one hundred:"}, {"id": "f2", "type": "textarea", "label": "What a thought and an action have in common, and how they differ:"}, {"id": "f3", "type": "textarea", "label": "Whether I would judge a friend by a thought they did not want, and why not:"}, {"id": "f4", "type": "textarea", "label": "A fairer sentence about what an unwanted thought means:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the original belief after this sheet:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'core beliefs', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('compulsion-vending-machine-that-keeps-the-coins-page', 'Compulsion Vending Machine That Keeps the Coins Page', 'act'::resource_kind, 'A metaphor page comparing a compulsion to a vending machine that takes the coin, rattles, and gives back less relief every time.', 'Use it to help a client see what the ritual is actually paying out and choose to keep the coin.', array['Adults', 'Teens']::text[], '20 minutes', 'Each ritual costs something, and the relief it dispenses shrinks while the price rises. The page has the client list what they feed the machine in time and attention, what came out the last few times, and how long the relief lasted. Then they practice keeping the coin once: noticing the urge, feeling the doubt rattle, and walking away with the coin toward something that matters. Watch for a client who kicks the machine, which is still a ritual.', '[{"id": "f0", "type": "textarea", "label": "What I put into the machine each day: minutes, attention, energy:"}, {"id": "f1", "type": "textarea", "label": "What came out the last three times, and how long the relief lasted:"}, {"id": "f2", "type": "textarea", "label": "What the machine promises versus what it actually dispenses:"}, {"id": "f3", "type": "textarea", "label": "One time this week I kept the coin, and what I spent it on instead:"}, {"id": "f4", "type": "textarea", "label": "What the urge did when the machine did not get its coin:"}, {"id": "f5", "type": "textarea", "label": "What I would do with a week of coins kept:"}]'::jsonb, array['OCD', 'metaphor', 'willingness', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('wise-mind-when-the-doubt-says-one-more-check-card', 'Wise Mind When the Doubt Says One More Check Card', 'dbt'::resource_kind, 'A wise mind card for the moment the doubt asks for one more check, hearing emotion mind and reasonable mind before the quiet answer.', 'Use it to give a client a brief pause and a wise mind question at the exact point where a check is about to happen.', array['Adults', 'Teens']::text[], 'Five minutes at the moment of an urge', 'One more check sounds reasonable and feels urgent, which is why it works. The card asks the client to name the emotion mind''s case, the reasonable mind''s case, and then take one slow breath and ask what wise mind knows about the doubt. Most clients already know the answer; the card just gives it a turn to speak. Watch for a client who uses the card and then checks anyway; that is still useful data about how the urge behaves when it is noticed.', '[{"id": "f0", "type": "textarea", "label": "What the doubt is asking me to check, and how urgent it feels, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says about why I must check:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says about the facts:"}, {"id": "f3", "type": "textarea", "label": "After one slow breath: what wise mind already knows about this doubt:"}, {"id": "f4", "type": "textarea", "label": "What I did, and what the urge did over the next ten minutes:"}]'::jsonb, array['OCD', 'wise mind', 'core DBT', 'urges']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('sticky-thought-lint-roller-play', 'Sticky Thought Lint Roller Play', 'kids'::resource_kind, 'A play where a child rolls a real lint roller over a drawing of a sticky thought, peels the sheet, and sees the thought lift away.', 'Use it to give a young child a hands-on picture of a thought that sticks and a way to let it unstick.', array['Children']::text[], '15 minutes', 'The child draws a sticky thought that keeps coming back onto a piece of paper and covers it with little scraps of paper or glitter. The parent hands them a lint roller and they roll the thought until the scraps lift, then peel the sheet and look at what came off. The parent says the thought was sticky, not true, and asks what the child wants to do now that it has been rolled. Repeat whenever the thought comes back. Watch for a parent who tries to argue with the thought; the roller does the work.', '[{"id": "f0", "type": "textarea", "label": "Draw your sticky thought:"}, {"id": "f1", "type": "textarea", "label": "What did it look like after you rolled it?"}, {"id": "f2", "type": "textarea", "label": "What did you see on the peeled-off sheet?"}, {"id": "f3", "type": "textarea", "label": "What did your grown-up say about sticky thoughts?"}, {"id": "f4", "type": "textarea", "label": "What do you want to do now that the thought is rolled away?"}]'::jsonb, array['OCD', 'children', 'play', 'intrusive thoughts']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('movie-theater-middle-row-plan-sheet', 'Movie Theater Middle Row Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a client who avoids theaters or sits by the exit, moving row by row toward the middle with a plan for each visit.', 'Use it to help a client reclaim theaters, concerts and lectures one seat closer to the middle at a time.', array['Adults', 'Teens']::text[], 'Four to six visits over several weeks', 'The dark, the crowd and the distance to the aisle make theaters a common place to stop going. The sheet maps the steps: aisle seat near the exit, aisle seat halfway back, three seats in, middle of the row, with a prediction and a result for each. The client plans what they will do if a surge comes, which is to stay seated and let it pass, and what they will not do, which is leave. Watch for a client who picks a quiet matinee every time; a full showing is a later step.', '[{"id": "f0", "type": "textarea", "label": "Where I sit now, if I go at all, and why that seat:"}, {"id": "f1", "type": "textarea", "label": "My steps, from where I sit now to the middle of the row:"}, {"id": "f2", "type": "textarea", "label": "For this visit: the seat, my prediction of what will happen, and how sure I am:"}, {"id": "f3", "type": "textarea", "label": "What I will do if a surge comes while I am seated:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, including how long any surge lasted:"}, {"id": "f5", "type": "textarea", "label": "The next seat, and when I will take it:"}]'::jsonb, array['panic attacks', 'exposure', 'avoidance', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('tingling-hands-means-something-serious-fact-check-sheet', 'Tingling Hands Means Something Serious Fact Check Sheet', 'cbt'::resource_kind, 'A fact check sheet for the tingling, numb or cold hands that come with a surge, with what else produces them and what has followed before.', 'Use it to help a client who reads tingling as a sign of something serious see where the sensation comes from.', array['Adults', 'Teens']::text[], '15 minutes', 'Tingling hands and face are among the most alarming sensations in a surge because they feel like a body failing. The sheet has the client describe the sensation, the conclusion they jump to, everything else that produces the same tingling such as fast breathing or gripping, how many times they have had it and what followed, and a fairer explanation. Reading from a check-up they have had can go in the evidence column if they have one. Watch for a client who seeks a new medical opinion after every surge; note it without judgment and bring it back to the record.', '[{"id": "f0", "type": "textarea", "label": "The sensation, exactly: where, how strong, how long:"}, {"id": "f1", "type": "textarea", "label": "The conclusion I jumped to, and how sure I was, zero to one hundred:"}, {"id": "f2", "type": "textarea", "label": "Everything else that produces this sensation, including fast breathing and gripping:"}, {"id": "f3", "type": "textarea", "label": "How many times I have had it, and what followed each time:"}, {"id": "f4", "type": "textarea", "label": "A fairer explanation that fits all of the evidence:"}, {"id": "f5", "type": "textarea", "label": "How sure I am of the serious conclusion now:"}]'::jsonb, array['panic attacks', 'panic', 'core CBT', 'evidence']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('fear-of-fear-loop-noticing-page', 'Fear of Fear Loop Noticing Page', 'act'::resource_kind, 'A noticing page that draws the loop in which fear of the next surge produces the sensations that start one, and finds a place to step out.', 'Use it to help a client see the fear of fear as a loop they can observe rather than a fact about their body.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw the loop with the client: watching for the sensation, finding it, fear of the surge, more sensation. The page asks where in the loop they usually notice themselves, what the mind says at each point, and where they could step out, usually by letting the sensation be there and turning attention outward. This is noticing, not fixing; the loop may still run. Watch for a client who uses the page to monitor themselves more closely, which is the first arrow of the loop.', '[{"id": "f0", "type": "textarea", "label": "The loop as it runs for me, step by step, in my own words:"}, {"id": "f1", "type": "textarea", "label": "The point in the loop where I usually first notice I am in it:"}, {"id": "f2", "type": "textarea", "label": "What my mind says at each step of the loop:"}, {"id": "f3", "type": "textarea", "label": "The point where I could step out, and what stepping out would look like:"}, {"id": "f4", "type": "textarea", "label": "One time this week I noticed the loop and let the sensation be there while I turned outward:"}, {"id": "f5", "type": "textarea", "label": "What the loop did when I stopped feeding it with attention:"}]'::jsonb, array['panic attacks', 'core ACT', 'mindfulness', 'panic']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('observe-the-breath-without-changing-it-card', 'Observe the Breath Without Changing It Card', 'dbt'::resource_kind, 'A mindfulness card for watching the breath exactly as it is during rising anxiety, without slowing, deepening or counting it.', 'Use it to give a client who has turned breathing into a struggle a way to let the breath breathe itself.', array['Adults', 'Teens']::text[], 'Five minutes, practiced daily and used during rising anxiety', 'Some clients have learned so many breathing techniques that every breath is a test. The card asks them to observe the breath as it is: short, fast, shallow, whatever it is doing, and to describe it in plain words without adjusting it. The breath often settles on its own once it is not being managed. Practice on calm days first. Watch for a client who reports doing it wrong; there is no wrong, only observing or controlling, and noticing the control is still observing.', '[{"id": "f0", "type": "textarea", "label": "What my breath was doing when I started watching: fast or slow, deep or shallow, where I felt it:"}, {"id": "f1", "type": "textarea", "label": "The urge to change it, and what the urge wanted me to do:"}, {"id": "f2", "type": "textarea", "label": "What the breath did over five minutes while I only watched:"}, {"id": "f3", "type": "textarea", "label": "Plain words I used to describe it, without good or bad:"}, {"id": "f4", "type": "textarea", "label": "One time this week I watched the breath during rising anxiety, and what happened:"}]'::jsonb, array['panic attacks', 'mindfulness', 'core DBT', 'breathing']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('night-waking-surge-response-card-for-partners', 'Night Waking Surge Response Card for Partners', 'couples'::resource_kind, 'A card for the partner of someone who wakes with a surge, with what to say, what not to do, and what the waking partner wants afterward.', 'Use it to turn a frightening night event into something both partners know how to handle.', array['Couples']::text[], '25 minutes to plan, used at night', 'Waking with a pounding heart in the dark is frightening for both people in the bed. The partner who wakes with surges writes what helps, what makes it worse, and what they want in the ten minutes afterward. The other partner writes what the nights are like for them and what they need in order not to panic too. They agree on a three-line script and a plan for getting back to sleep. Watch for a partner who takes charge and starts coaching breathing, which often makes it worse.', '[{"id": "f0", "type": "textarea", "label": "Partner who wakes with surges: what helps in the first minute, and what makes it worse:"}, {"id": "f1", "type": "textarea", "label": "Partner who wakes beside them: what these nights are like for me, and what I need to stay steady:"}, {"id": "f2", "type": "textarea", "label": "Our three-line script for the moment, in plain words:"}, {"id": "f3", "type": "textarea", "label": "What we each want in the ten minutes after the surge passes:"}, {"id": "f4", "type": "textarea", "label": "Our plan for getting back to sleep, including whether we talk or stay quiet:"}, {"id": "f5", "type": "textarea", "label": "After the next night it happens: what worked and what we will change:"}]'::jsonb, array['panic attacks', 'couples', 'support', 'sleep']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('homework-hour-role-reset-sheet', 'Homework Hour Role Reset Sheet', 'worksheet'::resource_kind, 'A sheet for a parent who has become the homework enforcer, redefining their role, the child''s role and the teacher''s role.', 'Use it to end the nightly homework fight by sorting out who is responsible for what.', array['Adults']::text[], '30 minutes', 'Homework fights are usually role fights: the parent has taken on checking, correcting and finishing. The sheet lists everything the parent currently does during homework, sorts each task into the child''s job, the parent''s job and the teacher''s job, and writes the parent''s new role in one sentence, often as the provider of a time, a place and a snack. It includes what the parent will do with the urge to step in. Watch for a parent who fears that letting work go in unfinished will reflect on them.', '[{"id": "f0", "type": "textarea", "label": "Everything I currently do during homework time, honestly:"}, {"id": "f1", "type": "textarea", "label": "Each task sorted: my child''s job, my job, the teacher''s job:"}, {"id": "f2", "type": "textarea", "label": "My new role during homework, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the urge to check, correct or finish:"}, {"id": "f4", "type": "textarea", "label": "What I will say to my child about the change, and when:"}, {"id": "f5", "type": "textarea", "label": "How the first week went, including what the teacher said, if anything:"}]'::jsonb, array['parenting', 'boundaries', 'routines', 'family']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('they-will-remember-this-forever-thought-check-sheet', 'They Will Remember This Forever Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the parent convinced that one lost temper or missed event will be the memory that defines their child''s childhood.', 'Use it to help a parent weigh a single hard moment against the whole of what their child experiences.', array['Adults']::text[], '20 minutes', 'After a bad moment, parents forecast a lifelong scar. The sheet records the moment, the forecast and its certainty, then what the parent remembers of their own parents'' worst moments and best ones, how many ordinary moments their child had this week, and what repair was done. It ends with a fairer forecast. Watch for a parent whose own childhood held real harm; this sheet is for ordinary bad moments, and their history deserves its own time.', '[{"id": "f0", "type": "textarea", "label": "The moment I am replaying, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "The forecast: what my child will remember and how it will shape them, and how sure I am:"}, {"id": "f2", "type": "textarea", "label": "What I actually remember of my own parents'' worst moments, and of their ordinary ones:"}, {"id": "f3", "type": "textarea", "label": "How many ordinary and good moments my child had with me this week:"}, {"id": "f4", "type": "textarea", "label": "The repair I did or can still do:"}, {"id": "f5", "type": "textarea", "label": "A fairer forecast of what this moment will mean in my child''s story:"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT', 'guilt']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('teen-eye-roll-willingness-page', 'Teen Eye Roll Willingness Page', 'act'::resource_kind, 'A willingness page for the parent stung by a teenager''s eye rolls and one-word answers, making room for the sting and staying present.', 'Use it to help a parent stay in contact with a teen who is pulling away without retaliating or withdrawing.', array['Adults']::text[], '20 minutes', 'The eye roll lands as rejection, and parents respond by lecturing or going quiet. The page names the feeling the eye roll brings, the story the mind tells about it, what the parent does when they buy the story, and what staying present would look like: a short warm comment, no lecture, a door left open. It plans one such moment this week. Watch for a parent who confuses willingness with tolerating rudeness; limits can still be set in a calm voice.', '[{"id": "f0", "type": "textarea", "label": "What I feel in my body when my teen rolls their eyes or answers in one word:"}, {"id": "f1", "type": "textarea", "label": "The story my mind tells about what it means:"}, {"id": "f2", "type": "textarea", "label": "What I usually do when I buy that story, and how it goes:"}, {"id": "f3", "type": "textarea", "label": "What staying present would look like instead, in a sentence or two:"}, {"id": "f4", "type": "textarea", "label": "One moment this week I made room for the sting and stayed present anyway:"}, {"id": "f5", "type": "textarea", "label": "What my teen did in the hour after, if anything:"}]'::jsonb, array['parenting', 'willingness', 'core ACT', 'family']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-lecturing-card-for-parents', 'Opposite Action to Lecturing Card for Parents', 'dbt'::resource_kind, 'An opposite action card for the parent whose urge, when upset, is to lecture, replacing the speech with one sentence and a pause.', 'Use it to help a parent notice the lecture urge and act opposite to it before the child stops listening.', array['Adults']::text[], 'Ten minutes to learn, used in the moment', 'The lecture urge comes from fear and frustration, and the speech that follows usually ends with the child looking at the floor. The card asks the parent to notice the urge, name the emotion under it, and do the opposite: one sentence stating the limit or the concern, then silence long enough for the child to answer. It logs the length of the pause and what the child did with it. Watch for a parent who delivers the one sentence in a lecturing tone; tone is part of the opposite action.', '[{"id": "f0", "type": "textarea", "label": "The moment the urge to lecture came, and the emotion I noticed underneath it:"}, {"id": "f1", "type": "textarea", "label": "The one sentence I said instead of the speech:"}, {"id": "f2", "type": "textarea", "label": "How long I stayed quiet afterward, roughly:"}, {"id": "f3", "type": "textarea", "label": "What my child said or did in the pause:"}, {"id": "f4", "type": "textarea", "label": "What my tone was like, honestly, and what I will adjust:"}]'::jsonb, array['parenting', 'opposite action', 'core DBT', 'communication']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('family-job-jar-craft', 'Family Job Jar Craft', 'kids'::resource_kind, 'A craft where the family decorates a jar and fills it with job sticks the child helped write, drawn at a set time each day.', 'Use it to turn chores into a game of chance a child runs, with the parent as fellow player rather than enforcer.', array['Children']::text[], '30 minutes to make, daily to use', 'The child decorates a jar and the family writes small jobs on craft sticks: feed the cat, match socks, wipe the table. A few sticks are joke jobs like hop around the kitchen. At the agreed time each day every family member, parents included, draws a stick and does the job. The parent draws too and does their job visibly. Watch for a parent who loads the jar with the child''s jobs only; the game works because everyone plays.', '[{"id": "f0", "type": "textarea", "label": "Draw your job jar and some of the sticks inside it:"}, {"id": "f1", "type": "textarea", "label": "What jobs did you help write on the sticks?"}, {"id": "f2", "type": "textarea", "label": "What job did your grown-up draw today, and did they do it?"}, {"id": "f3", "type": "textarea", "label": "Which joke job is your favorite?"}, {"id": "f4", "type": "textarea", "label": "What is different about jobs when you draw them from the jar?"}]'::jsonb, array['parenting', 'children', 'craft', 'routines']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('first-week-home-alone-with-the-baby-plan-sheet', 'First Week Home Alone With the Baby Plan Sheet', 'worksheet'::resource_kind, 'A plan for the first week a new parent is home alone with the baby after the other returns to work, with anchors and lifelines.', 'Use it to help a new parent face the first solo week with a shape to the day and people they can reach.', array['Adults']::text[], '30 minutes to plan, one week to use', 'The first solo week often arrives with no plan and a lot of dread. The sheet divides a day into rough blocks, names one small anchor for each, such as a walk at ten, lists three people who can be called or texted during the day and what the parent would say, and sets a tiny standard for the day that does not include a clean house. Watch for a parent who plans a full schedule; the anchors are there to be missed and returned to, not completed.', '[{"id": "f0", "type": "textarea", "label": "My day in rough blocks, with one small anchor in each:"}, {"id": "f1", "type": "textarea", "label": "Three people I can text or call during the day, and the first line I would send:"}, {"id": "f2", "type": "textarea", "label": "What counts as a good enough day this week, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the hardest hour, the one I am most dreading:"}, {"id": "f4", "type": "textarea", "label": "What I want my partner to do when they get home, specifically:"}, {"id": "f5", "type": "textarea", "label": "After the week: which anchors held, and what I learned about the hard hour:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'support', 'routines']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('if-i-nap-the-baby-will-need-me-rule-check-sheet', 'If I Nap the Baby Will Need Me Rule Check Sheet', 'cbt'::resource_kind, 'A rule check for the new parent who cannot sleep when the baby sleeps because resting feels like leaving their post.', 'Use it to loosen the rule that keeps an exhausted parent awake and test what actually happens when they rest.', array['Adults']::text[], '20 minutes, then one week', 'The rule says a sleeping parent is an unavailable parent. The sheet writes it out, lists the evidence for it and the times the baby slept through a parent''s nap, plans a single rest with a monitor or a partner on watch, and records what happened. Review the belief rating after three rests. Watch for a parent whose refusal to rest is also about not trusting the other caregiver; that is a different conversation worth having.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words: if I rest, then…"}, {"id": "f1", "type": "textarea", "label": "What I believe will happen if the baby wakes and I am asleep:"}, {"id": "f2", "type": "textarea", "label": "Times the baby has slept while I was sleeping, and what happened:"}, {"id": "f3", "type": "textarea", "label": "My planned rest: when, how long, and who or what is on watch:"}, {"id": "f4", "type": "textarea", "label": "What actually happened during and after the rest:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the rule now, and my next rest:"}]'::jsonb, array['perinatal and postpartum', 'core beliefs', 'sleep', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('the-parent-i-am-becoming-not-the-one-i-pictured-page', 'The Parent I Am Becoming Not the One I Pictured Page', 'act'::resource_kind, 'A values page that sets the imagined parent beside the real one and finds what the client actually cares about in the gap.', 'Use it to help a new parent grieve the imagined version and choose what kind of parent to be with the one they have become.', array['Adults']::text[], '25 minutes', 'Before the baby there was a picture: patient, glowing, rested. The page has the client describe that picture without mocking it, then describe the parent they actually are this week, and then look for the values that were hiding in the picture. Most of them can be acted on by the tired real parent in some small form. Watch for a client who treats the gap as failure; the picture was never a person, and the page should say so.', '[{"id": "f0", "type": "textarea", "label": "The parent I pictured before the baby came, described honestly and kindly:"}, {"id": "f1", "type": "textarea", "label": "The parent I actually am this week, described honestly and kindly:"}, {"id": "f2", "type": "textarea", "label": "What I feel looking at the two side by side:"}, {"id": "f3", "type": "textarea", "label": "The values that were hiding in the picture: what the imagined parent cared about:"}, {"id": "f4", "type": "textarea", "label": "One small way the real, tired parent can act on each value this week:"}, {"id": "f5", "type": "textarea", "label": "One thing the real parent does that the imagined one never could:"}]'::jsonb, array['perinatal and postpartum', 'values', 'core ACT', 'acceptance']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('wise-mind-return-to-work-decision-sheet-for-new-parents', 'Wise Mind Return to Work Decision Sheet for New Parents', 'dbt'::resource_kind, 'A wise mind sheet for the decision about when and whether to return to work after a baby, with emotion mind and reasonable mind each heard.', 'Use it to help a new parent make a weighted decision instead of one driven by the loudest voice that week.', array['Adults']::text[], '30 minutes', 'The decision about returning to work swings with the night before. The sheet gives emotion mind its full say, including guilt in both directions, then reasonable mind its say about money, roles and logistics, then asks the client to sit quietly and write what wise mind knows. It ends with a decision that can be revisited at a set date. Watch for a client who lets a relative''s voice stand in for reasonable mind; ask whose list that is.', '[{"id": "f0", "type": "textarea", "label": "Everything emotion mind says about going back and about staying home, including the guilt in both directions:"}, {"id": "f1", "type": "textarea", "label": "Everything reasonable mind says: money, roles, logistics, what the job allows:"}, {"id": "f2", "type": "textarea", "label": "After a quiet minute: what wise mind knows about this decision:"}, {"id": "f3", "type": "textarea", "label": "The decision I am making for now:"}, {"id": "f4", "type": "textarea", "label": "The date I will revisit it, and what would make me change it:"}, {"id": "f5", "type": "textarea", "label": "Who I need to tell, and the sentence I will use:"}]'::jsonb, array['perinatal and postpartum', 'wise mind', 'decisions', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('first-night-out-without-the-baby-plan-for-partners', 'First Night Out Without the Baby Plan for Partners', 'couples'::resource_kind, 'A plan for a couple''s first evening out since the baby, with each partner''s worries, the sitter plan and topics besides the baby.', 'Use it to get a new-parent couple out the door together and give the evening a chance of being about them.', array['Couples']::text[], '25 minutes', 'The first night out is often canceled three times and then spent checking the phone. Each partner writes what they are worried about leaving and what they are hoping for from the evening; together they decide the sitter, the check-in rule, the length, and three topics that are not the baby. Watch for a mismatch where one partner is desperate to go and the other is not ready; the plan can start with ninety minutes at a place around the corner.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what I am worried about leaving, and what I hope for from the evening:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what I am worried about leaving, and what I hope for from the evening:"}, {"id": "f2", "type": "textarea", "label": "Our sitter plan, and the check-in rule we both agree to:"}, {"id": "f3", "type": "textarea", "label": "How long we will be out, and where:"}, {"id": "f4", "type": "textarea", "label": "Three things we will talk about that are not the baby:"}, {"id": "f5", "type": "textarea", "label": "How the evening went, and when the next one is:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'connection', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('things-i-am-allowed-to-be-bad-at-list-sheet', 'Things I Am Allowed to Be Bad At List Sheet', 'worksheet'::resource_kind, 'A list-making sheet of skills and roles the client gives themselves permission to be ordinary or poor at, with what the permission frees up.', 'Use it to help a client who must be good at everything decide on purpose where they can be bad.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients with fragile worth often hold an unspoken rule that they must be competent everywhere. The sheet has them list the things they are currently bad at and ashamed of, then choose which of those they are willing to stay bad at on purpose, writing a permission sentence for each and what the freed effort could go toward. Watch for a client who can only grant permission for trivial things; ask about one that costs them real energy, such as cooking or small talk.', '[{"id": "f0", "type": "textarea", "label": "Things I am bad at that I feel ashamed of:"}, {"id": "f1", "type": "textarea", "label": "Which of these actually matter to my life, and which only matter to the rule:"}, {"id": "f2", "type": "textarea", "label": "The ones I give myself permission to stay bad at, with a sentence for each: I am allowed to be bad at…"}, {"id": "f3", "type": "textarea", "label": "What I have spent trying to be good at them, in time and worry:"}, {"id": "f4", "type": "textarea", "label": "Where that effort could go instead:"}, {"id": "f5", "type": "textarea", "label": "One thing I did badly this week on purpose, and what happened:"}]'::jsonb, array['self-esteem', 'self-compassion', 'perfectionism', 'values']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('i-am-only-as-good-as-my-last-performance-rule-sheet', 'I Am Only as Good as My Last Performance Rule Sheet', 'cbt'::resource_kind, 'A rule-testing sheet for the belief that worth resets with every result, with a timeline of performances and the worth line drawn beside it.', 'Use it to show a client how a result-by-result worth rule behaves and to draft a steadier rule.', array['Adults', 'Teens']::text[], '25 minutes', 'Under this rule, a good week is relief and a bad one is a verdict. The client lists their last ten performances in any area that matters, rates each, and draws how their sense of worth moved alongside. They then look at what the rule would say about someone they respect who had a bad month, and draft a rule in which worth is a floor rather than a score. Watch for a client who agrees the rule is unfair and keeps it because it motivates them; ask what it has cost on the bad weeks.', '[{"id": "f0", "type": "textarea", "label": "My last ten performances in an area that matters to me, with a rating for each:"}, {"id": "f1", "type": "textarea", "label": "How my sense of my own worth moved with each one:"}, {"id": "f2", "type": "textarea", "label": "What this rule would say about someone I respect after a bad month:"}, {"id": "f3", "type": "textarea", "label": "What the rule has given me, honestly, and what it has cost:"}, {"id": "f4", "type": "textarea", "label": "A steadier rule in which worth is a floor, not a score:"}, {"id": "f5", "type": "textarea", "label": "What I will do differently after the next poor performance:"}]'::jsonb, array['self-esteem', 'core beliefs', 'core CBT', 'perfectionism']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('inner-judge-in-the-back-row-defusion-page', 'Inner Judge in the Back Row Defusion Page', 'act'::resource_kind, 'A defusion page that places the client''s inner judge in the back row of a theater, still talking, while the client goes on with the scene.', 'Use it to help a client keep acting while the critical commentary continues, rather than waiting for it to stop.', array['Adults', 'Teens']::text[], '20 minutes', 'The judge cannot be removed from the theater, but it can be seated. The page has the client write the judge''s typical lines, picture it in the back row with its program and its sighs, and practice continuing the scene: the conversation, the task, the first attempt. Afterward they note what the judge said and what they did anyway. Watch for a client who turns around to argue with the back row; that stops the scene, which is what the judge wanted.', '[{"id": "f0", "type": "textarea", "label": "The judge''s usual lines, written as it says them:"}, {"id": "f1", "type": "textarea", "label": "Where I picture it sitting, and what it looks like from the stage:"}, {"id": "f2", "type": "textarea", "label": "A scene this week I played while the judge kept talking:"}, {"id": "f3", "type": "textarea", "label": "What the judge said during the scene, and what I did anyway:"}, {"id": "f4", "type": "textarea", "label": "What happened to the volume of the judge when I stopped turning around:"}, {"id": "f5", "type": "textarea", "label": "What I want the next scene to be:"}]'::jsonb, array['self-esteem', 'defusion', 'self-criticism', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('fast-skill-when-someone-takes-credit-for-my-work-card', 'FAST Skill When Someone Takes Credit for My Work Card', 'dbt'::resource_kind, 'A FAST card for the moment a colleague or classmate takes credit, keeping self-respect while saying what happened.', 'Use it to help a client who goes quiet when credit is taken keep their self-respect in the moment.', array['Adults', 'Teens']::text[], '20 minutes to script, used once', 'When credit is taken, clients with low self-worth often say nothing and then rehearse for days. The card scripts the FAST skill: fair to both people, no apologizing for speaking, sticking to the facts of who did what, and truthful without exaggeration. It includes the sentence they will use in the moment and the follow-up message if the moment passes. Watch for a script that is really an attack on the other person; fairness includes them.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts: what I did, and what was said about who did it:"}, {"id": "f1", "type": "textarea", "label": "Fair: what is fair to me and to the other person here:"}, {"id": "f2", "type": "textarea", "label": "No apologies: the sentence I will say, with every sorry removed:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: what matters to me in how I handle this, beyond the credit:"}, {"id": "f4", "type": "textarea", "label": "Truthful: the facts I will state, without making it bigger or smaller:"}, {"id": "f5", "type": "textarea", "label": "What I said or sent, and how I felt about myself afterward:"}]'::jsonb, array['self-esteem', 'FAST', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('pass-the-trophy-reason-game', 'Pass the Trophy Reason Game', 'game'::resource_kind, 'A group game where a toy trophy passes around and each holder is given one specific reason by the passer that they deserve it.', 'Use it to practice giving and receiving specific recognition in a group that is used to deflecting it.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'A toy trophy or any object stands in. The first player hands it to someone and states one specific thing they have seen that person do, not a general compliment. The receiver may only say thank you, then passes it on with their own reason to someone who has not held it. Everyone holds it once; a second round goes the other way. Debrief how receiving felt compared with giving. Watch for jokes used to deflect; gently ask for the thank you and nothing else.', '[{"id": "f0", "type": "textarea", "label": "What reason did someone give when they handed you the trophy?"}, {"id": "f1", "type": "textarea", "label": "What was it like to say only thank you?"}, {"id": "f2", "type": "textarea", "label": "Who did you pass it to, and what specific thing did you name?"}, {"id": "f3", "type": "textarea", "label": "Which was harder for you, giving the reason or receiving one?"}, {"id": "f4", "type": "textarea", "label": "One reason you would give yourself the trophy this week:"}]'::jsonb, array['self-esteem', 'group', 'game', 'strengths']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('eating-lunch-in-the-break-room-steps-sheet', 'Eating Lunch in the Break Room Steps Sheet', 'worksheet'::resource_kind, 'A step plan for a client who eats lunch at their desk or in the car to avoid the break room, with a seat and a goal for each step.', 'Use it to help a client return to the shared lunch space one step at a time, with a plan for the silence.', array['Adults', 'Teens']::text[], 'Two to three weeks', 'Eating in front of others while making conversation is two fears at once. The sheet builds steps: coffee only at the edge of the room, lunch at a side table with headphones, lunch at the main table reading, lunch with one question asked, with a prediction and a result for each. It includes what the client will do with a silence. Watch for safety behaviors such as always having a phone out; make phone-free a later step rather than banning it at the start.', '[{"id": "f0", "type": "textarea", "label": "Where I eat lunch now, and what I avoid by eating there:"}, {"id": "f1", "type": "textarea", "label": "My steps, from the edge of the room to a conversation at the main table:"}, {"id": "f2", "type": "textarea", "label": "For this step: where I will sit, my prediction, and how sure I am:"}, {"id": "f3", "type": "textarea", "label": "What I will do with a silence, and what I will say if someone sits down:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, and how long the discomfort lasted:"}, {"id": "f5", "type": "textarea", "label": "The next step, and the day I will take it:"}]'::jsonb, array['social anxiety', 'exposure', 'avoidance', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('i-have-to-be-interesting-to-be-welcome-rule-test-sheet', 'I Have to Be Interesting to Be Welcome Rule Test Sheet', 'cbt'::resource_kind, 'A rule-testing sheet for the belief that the client must be interesting to be wanted, with a planned ordinary conversation and the result.', 'Use it to help a client stop auditioning in conversation and test whether ordinary is enough.', array['Adults', 'Teens']::text[], 'One week', 'The rule turns every conversation into a performance review. The sheet writes it out, lists the evidence the client uses for it, then plans a deliberately ordinary conversation: no stories prepared, questions and small observations only. The client predicts how the other person will react and records what happened, including whether the conversation continued. Watch for a client who judges the test by their own discomfort rather than by the other person''s behavior.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words: to be welcome I have to…"}, {"id": "f1", "type": "textarea", "label": "The evidence I have been using for it, and where the rule came from:"}, {"id": "f2", "type": "textarea", "label": "My planned ordinary conversation: with whom, where, and what I will not do:"}, {"id": "f3", "type": "textarea", "label": "My prediction of how they will react, and how sure I am:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, judged by what they did, not by how I felt:"}, {"id": "f5", "type": "textarea", "label": "What the rule looks like after this test:"}]'::jsonb, array['social anxiety', 'core beliefs', 'behavioral experiment', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('the-everyone-is-judging-me-story-naming-page', 'The Everyone Is Judging Me Story Naming Page', 'act'::resource_kind, 'A defusion page that gives the client''s most familiar social story a title and practices greeting it by name when it shows up.', 'Use it to help a client step back from the judging story the moment it starts, without arguing with it.', array['Adults', 'Teens']::text[], '15 minutes', 'The story is old and well rehearsed, and it arrives whole. The page has the client write it out as a short script, give it a title, note the situations where it reliably plays, and practice greeting it: here is the judging story again. Then they turn attention to the person in front of them and record what they actually noticed. Watch for a client who names the story and then checks whether it is true, which reopens the argument the name was meant to close.', '[{"id": "f0", "type": "textarea", "label": "The story, written out as my mind tells it:"}, {"id": "f1", "type": "textarea", "label": "The title I am giving it:"}, {"id": "f2", "type": "textarea", "label": "The situations where it reliably plays:"}, {"id": "f3", "type": "textarea", "label": "My greeting line for when it starts:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the actual person in front of me after greeting the story:"}, {"id": "f5", "type": "textarea", "label": "One time this week the story played and I stayed in the conversation:"}]'::jsonb, array['social anxiety', 'defusion', 'core ACT', 'mindfulness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('give-skills-for-talking-to-the-barista-card', 'GIVE Skills for Talking to the Barista Card', 'dbt'::resource_kind, 'A GIVE skills card for the brief exchange at a counter, practicing gentle, interested, validating and easy manner in thirty seconds.', 'Use it to give a client a daily, low-stakes place to practice GIVE skills before using them somewhere that matters.', array['Adults', 'Teens']::text[], 'Thirty seconds daily for a week', 'Counter exchanges are short, repeated and forgiving, which makes them ideal practice. The card asks the client to use GIVE at the counter: a gentle tone, one interested question or comment, a validating line about a busy morning, and an easy manner such as a small smile. They log the exchange and the other person''s response. Watch for a client who scripts the whole exchange; the point is manner, not lines, and the barista will not follow the script anyway.', '[{"id": "f0", "type": "textarea", "label": "Where I practiced today, and the one interested comment or question I used:"}, {"id": "f1", "type": "textarea", "label": "The validating line I offered, if there was a chance:"}, {"id": "f2", "type": "textarea", "label": "What my tone and face were doing, as far as I could tell:"}, {"id": "f3", "type": "textarea", "label": "How the other person responded:"}, {"id": "f4", "type": "textarea", "label": "What I noticed in my body before, during and after the thirty seconds:"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('expert-on-nothing-improv-interview-game', 'Expert on Nothing Improv Interview Game', 'game'::resource_kind, 'An improv game where each player is interviewed as the world''s expert on a silly topic and must answer with confidence for one minute.', 'Use it to let a group practice being watched, speaking without preparation and surviving the awkward moment through play.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'A player draws a topic card, such as the history of left socks, and sits in the expert''s chair. The interviewer, another player, asks three serious questions; the expert must answer confidently and the audience must take notes as if it were real. One minute, then applause and the next expert. Everyone takes both roles once. Debrief what it was like to be watched while improvising nonsense. Watch for a player who freezes; the interviewer''s job is to ask an easier question, not to wait.', '[{"id": "f0", "type": "textarea", "label": "What topic were you the expert on, and what was your best answer?"}, {"id": "f1", "type": "textarea", "label": "What did you feel in your body in the expert''s chair, and how did it change over the minute?"}, {"id": "f2", "type": "textarea", "label": "What was it like to be the interviewer?"}, {"id": "f3", "type": "textarea", "label": "Which other expert made you laugh, and what did that do to your nerves?"}, {"id": "f4", "type": "textarea", "label": "What did you learn about being watched while making it up?"}]'::jsonb, array['social anxiety', 'group', 'game', 'exposure']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('their-phone-number-and-online-accounts-decision-sheet', 'Their Phone Number and Online Accounts Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the deceased''s phone number, voicemail, accounts and subscriptions, one item at a time, on the client''s timeline.', 'Use it to help a grieving client make the digital decisions in order, keeping what matters and letting go of what hurts.', array['Adults']::text[], '30 minutes, then as needed', 'The phone number still rings, the profile still has a birthday, the subscriptions still bill. The sheet lists each digital trace, what the client feels about it, what they want to keep from it such as a voicemail saved elsewhere, and whether now, later or never is the time. Nothing has to be decided today. Watch for a client who is pressured by a relative to close everything quickly, and for one who pays for a phone line for a year to hear the greeting; both deserve gentle discussion.', '[{"id": "f0", "type": "textarea", "label": "Every digital trace I know of: phone, voicemail, email, social accounts, subscriptions, photos in the cloud:"}, {"id": "f1", "type": "textarea", "label": "What I feel about each one, honestly:"}, {"id": "f2", "type": "textarea", "label": "What I want to save from each before anything changes, such as a voicemail or photos:"}, {"id": "f3", "type": "textarea", "label": "For each: now, later, or never, and who could help with the practical part:"}, {"id": "f4", "type": "textarea", "label": "The one I will handle this month, and how I will look after myself afterward:"}, {"id": "f5", "type": "textarea", "label": "What I want anyone pressuring me to know about my timeline:"}]'::jsonb, array['grief and loss', 'decisions', 'pacing', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('i-am-grieving-wrong-comparison-check-sheet', 'I Am Grieving Wrong Comparison Check Sheet', 'cbt'::resource_kind, 'A check sheet for the grieving client who compares their grief with a sibling''s, a book''s or a timeline and finds it wrong.', 'Use it to loosen the idea that there is a correct way to grieve that the client is failing to follow.', array['Adults', 'Teens']::text[], '20 minutes', 'Grief invites comparison: the sibling who cries more, the friend who is back at work, the stage the book says they should be in. The sheet names the comparison, the rule it implies, the evidence that grief varies between people who loved the same person, and what the client''s own grief actually looks like, described without a grade. Watch for a client who is being told they are grieving wrong by family; the sheet can help them find the sentence that answers that.', '[{"id": "f0", "type": "textarea", "label": "Who or what I compare my grief with, and how mine comes up short:"}, {"id": "f1", "type": "textarea", "label": "The rule the comparison implies about how grief should look:"}, {"id": "f2", "type": "textarea", "label": "What I know about how differently people who loved the same person grieve:"}, {"id": "f3", "type": "textarea", "label": "What my grief actually looks like this week, described without a grade:"}, {"id": "f4", "type": "textarea", "label": "What my grief is doing for me, if anything:"}, {"id": "f5", "type": "textarea", "label": "A sentence I can say to anyone, including myself, who says I am grieving wrong:"}]'::jsonb, array['grief and loss', 'thinking traps', 'core CBT', 'self-compassion']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('milestones-they-will-miss-willingness-page', 'Milestones They Will Miss Willingness Page', 'act'::resource_kind, 'A willingness page for the weddings, graduations and births the deceased will not see, planning how to carry them into those days.', 'Use it to help a client face a coming milestone with the loss present rather than avoiding the day or numbing through it.', array['Adults', 'Teens']::text[], '25 minutes', 'The milestone is coming and the person will not be there. The page names the day, what the client fears feeling, what they will carry of the person into it, such as an object, a toast or a quiet minute, and what they will do if grief arrives in the middle of the ceremony. It finishes with what they would want for themselves on that day. Watch for a client who plans to skip the day; honor the wish, then ask what their person would want them to see.', '[{"id": "f0", "type": "textarea", "label": "The milestone, and the moment in it where I expect to feel the absence most:"}, {"id": "f1", "type": "textarea", "label": "What I am afraid of feeling there, and what I usually do to avoid that feeling:"}, {"id": "f2", "type": "textarea", "label": "What of them I will carry into the day: an object, a toast, a quiet minute, a story:"}, {"id": "f3", "type": "textarea", "label": "What I will do if grief arrives in the middle of it:"}, {"id": "f4", "type": "textarea", "label": "What I want for myself on that day, grief included:"}, {"id": "f5", "type": "textarea", "label": "Who will know the plan so I am not carrying it alone:"}]'::jsonb, array['grief and loss', 'willingness', 'core ACT', 'values']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('grief-ambush-in-the-grocery-store-riding-the-wave-card', 'Grief Ambush in the Grocery Store Riding the Wave Card', 'dbt'::resource_kind, 'A card for the sudden wave of grief in a public place, with a thirty-second plan for riding it where the client stands.', 'Use it to give a grieving client a plan for the ambush in aisle four, so public places stop feeling dangerous.', array['Adults', 'Teens']::text[], 'Five minutes to learn, used as needed', 'Their favorite cereal, their song over the speakers: the wave comes without warning. The card gives the client a sequence for the first thirty seconds: hand on the cart, feet on the floor, name the wave, let it rise and crest, breathe out longer than in, and decide whether to continue or step outside. Both are allowed. Watch for a client who begins avoiding the store; the card is there to make the store possible, and the avoidance deserves a plan of its own.', '[{"id": "f0", "type": "textarea", "label": "Where the wave caught me, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "What I did in the first thirty seconds, from the card or otherwise:"}, {"id": "f2", "type": "textarea", "label": "How high the wave rose and roughly how long until it crested:"}, {"id": "f3", "type": "textarea", "label": "Whether I stayed or stepped out, and how I feel about that choice:"}, {"id": "f4", "type": "textarea", "label": "What I want to remember for the next ambush:"}]'::jsonb, array['grief and loss', 'distress tolerance', 'core DBT', 'grounding']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('memory-garden-stepping-stone-craft', 'Memory Garden Stepping Stone Craft', 'kids'::resource_kind, 'A craft where a child decorates a stepping stone for someone who died and the family places it in a garden or pot together.', 'Use it to give a grieving child a place to put their love that they can visit, made with their own hands.', array['Children']::text[], '45 minutes to make, placed together', 'Using a plain paver, air-dry clay or a stone, the child decorates a stepping stone with paint, shells, beads or a handprint, and chooses one word or picture for the person. The parent helps with the materials, shares a memory while they work, and lets the child decide where it goes: a garden bed, a pot on a balcony. They place it together and the parent says the person''s name out loud. Watch for a parent who hides their own tears from the child; naming them teaches that grief is allowed.', '[{"id": "f0", "type": "textarea", "label": "Draw your stepping stone and what you put on it:"}, {"id": "f1", "type": "textarea", "label": "What word or picture did you choose for the person, and why?"}, {"id": "f2", "type": "textarea", "label": "What memory did your grown-up share while you were making it?"}, {"id": "f3", "type": "textarea", "label": "Where did you decide to put the stone?"}, {"id": "f4", "type": "textarea", "label": "What do you want to do when you visit the stone?"}]'::jsonb, array['grief and loss', 'children', 'craft', 'family']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('adult-sibling-score-settling-pattern-sheet', 'Adult Sibling Score Settling Pattern Sheet', 'worksheet'::resource_kind, 'A pattern sheet for the adult sibling relationship still running on old scores, with the recurring fight mapped and one move changed.', 'Use it to help a client see the childhood pattern in the current sibling fight and choose a different first move.', array['Adults']::text[], '40 minutes', 'Adult siblings often argue about a parent''s care or a holiday while actually settling a score from decades ago. The sheet maps the most recent fight, the old script underneath it, the role each sibling falls into, and what each is really asking for. It ends with one move the client will change next time, usually the opening line. Watch for a client who wants to fix the sibling; the sheet changes one side of a two-sided pattern.', '[{"id": "f0", "type": "textarea", "label": "The most recent fight with my sibling, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "The old score underneath it, from when we were younger:"}, {"id": "f2", "type": "textarea", "label": "The role I fall into with them, and the role they fall into with me:"}, {"id": "f3", "type": "textarea", "label": "What I am actually asking for from them, underneath the argument:"}, {"id": "f4", "type": "textarea", "label": "What I think they are actually asking for:"}, {"id": "f5", "type": "textarea", "label": "The one move I will change next time, probably my first line:"}]'::jsonb, array['relationship issues', 'family', 'pattern', 'conflict']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('they-should-just-know-mind-reading-expectation-sheet', 'They Should Just Know Mind Reading Expectation Sheet', 'cbt'::resource_kind, 'A sheet for the expectation that a partner or friend should know what the client needs unasked, with the rule tested on a real need.', 'Use it to help a client turn a silent expectation into a spoken request and see what changes.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'The rule that love means knowing without asking produces hurt on one side and confusion on the other. The sheet captures a recent need that went unmet, the rule the client applied, how the other person could have known, and what asking would cost according to the rule. Then the client asks for one need plainly and records what happened. Watch for an ask delivered as a test, with the real need still hidden.', '[{"id": "f0", "type": "textarea", "label": "A recent need I had that someone close to me did not meet:"}, {"id": "f1", "type": "textarea", "label": "The rule I applied: they should have known because…"}, {"id": "f2", "type": "textarea", "label": "How, realistically, they could have known without being told:"}, {"id": "f3", "type": "textarea", "label": "What the rule says asking would mean about me or about them:"}, {"id": "f4", "type": "textarea", "label": "The need I asked for plainly this week, and the words I used:"}, {"id": "f5", "type": "textarea", "label": "What happened, and what the rule looks like now:"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('keeping-score-or-keeping-company-choice-point-page', 'Keeping Score or Keeping Company Choice Point Page', 'act'::resource_kind, 'A choice point page for the moment in a relationship when the client can tally a wrong or stay in the company of the person.', 'Use it to help a client notice the pull toward scorekeeping and choose the move that serves the relationship they want.', array['Adults', 'Teens']::text[], '20 minutes', 'The choice point arrives dozens of times a week: a late text, a forgotten errand, a tone. The page maps what pulls the client toward the tally, what the tally gives and costs, what keeping company would look like in the same moment, and which move points toward the relationship they say they want. It is not about never raising a problem; it is about which move the client is making and why. Watch for a client who hears it as a demand to swallow everything.', '[{"id": "f0", "type": "textarea", "label": "A recent moment where I could have kept score or kept company:"}, {"id": "f1", "type": "textarea", "label": "What pulled me toward the tally, and what the tally promised:"}, {"id": "f2", "type": "textarea", "label": "What keeping score has given me and cost me in this relationship:"}, {"id": "f3", "type": "textarea", "label": "What keeping company would have looked like in that moment:"}, {"id": "f4", "type": "textarea", "label": "The relationship I say I want, in a sentence, and which move points toward it:"}, {"id": "f5", "type": "textarea", "label": "One moment this week I noticed the choice point and chose on purpose:"}]'::jsonb, array['relationship issues', 'choice point', 'values', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('fast-when-lending-money-to-family-card', 'FAST When Lending Money to Family Card', 'dbt'::resource_kind, 'A FAST card for the request to lend money to a relative, keeping self-respect whether the answer is yes, no, or a smaller yes.', 'Use it to help a client who always says yes to family money requests answer from values instead of guilt.', array['Adults']::text[], '20 minutes', 'Money requests from family press every button. The card walks the FAST skill: what is fair to the client and the relative, the answer without apology, the values at stake such as the client''s own stability, and a truthful answer that does not invent reasons. It includes the sentence for a no and the terms for a yes. Watch for a yes given to end the discomfort, and for a no that comes wrapped in a lecture about the relative''s choices.', '[{"id": "f0", "type": "textarea", "label": "The request, who made it, and how I felt when it came:"}, {"id": "f1", "type": "textarea", "label": "Fair: what is fair to me, and what is fair to them:"}, {"id": "f2", "type": "textarea", "label": "No apologies: my answer, with the sorry removed:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: what matters to me here, including my own stability:"}, {"id": "f4", "type": "textarea", "label": "Truthful: the honest reason, without inventing one:"}, {"id": "f5", "type": "textarea", "label": "What I said, and how I felt about myself afterward:"}]'::jsonb, array['relationship issues', 'FAST', 'boundaries', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('who-apologizes-first-standoff-sheet-for-partners', 'Who Apologizes First Standoff Sheet for Partners', 'couples'::resource_kind, 'A sheet for the couple who can go days waiting for the other to apologize first, with what each is protecting and a way to end the standoff.', 'Use it to help partners see what the standoff costs them both and agree on a first move neither has to lose by making.', array['Couples']::text[], '35 minutes', 'After a fight, both partners wait, and the silence hardens. Each writes what apologizing first would mean about them, what they are protecting by waiting, and what the days of silence cost. Together they look for a first move that is not a surrender: a touch, a shared chore, a line they agree means I am ready when you are. Watch for a partner for whom apologizing first has a long family history; that story belongs in the room.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what apologizing first would mean about me, and what I am protecting by waiting:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what apologizing first would mean about me, and what I am protecting by waiting:"}, {"id": "f2", "type": "textarea", "label": "What the standoff days cost each of us, and what they cost the relationship:"}, {"id": "f3", "type": "textarea", "label": "A first move neither of us loses by making, and the line that goes with it:"}, {"id": "f4", "type": "textarea", "label": "What the other partner will do when the first move is made:"}, {"id": "f5", "type": "textarea", "label": "The next time we used it, and how long the silence lasted compared with before:"}]'::jsonb, array['relationship issues', 'couples', 'repair', 'conflict']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('crowded-train-spot-and-exit-plan-sheet', 'Crowded Train Spot and Exit Plan Sheet', 'worksheet'::resource_kind, 'A plan for a client who avoids crowded transit, choosing where to stand, what to hold onto, and how to leave if a car becomes too much.', 'Use it to help a client get back onto buses and trains with a plan for their body and an exit they know.', array['Adults', 'Teens']::text[], '30 minutes to plan, used on each ride', 'Being pressed against strangers can be unbearable for someone with a history of unwanted touch. The sheet plans the ride: the car and the spot, often by the door or against a wall, what to hold and look at, a grounding anchor for the body, the stop where they can step off and wait for the next one, and who they will text when they arrive. Nothing about what happened is asked. Watch for a client who plans to endure the ride by dissociating; the aim is to stay present and in control of the exit.', '[{"id": "f0", "type": "textarea", "label": "The ride I want to make, and what about it is hardest:"}, {"id": "f1", "type": "textarea", "label": "Where I will stand or sit, and what I will hold onto:"}, {"id": "f2", "type": "textarea", "label": "What I will look at and what I will feel under my feet to stay here, now:"}, {"id": "f3", "type": "textarea", "label": "The stop where I can step off and wait for the next train if I need to:"}, {"id": "f4", "type": "textarea", "label": "Who I will text when I arrive, and what I will say:"}, {"id": "f5", "type": "textarea", "label": "How the ride went, and what I will keep for the next one:"}]'::jsonb, array['sexual abuse', 'safety', 'grounding', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('being-believed-prediction-check-sheet', 'Being Believed Prediction Check Sheet', 'cbt'::resource_kind, 'A prediction sheet for a client afraid that a safe person will not believe them, completed in session, without writing what happened.', 'Use it to help a client test the fear of disbelief with a trusted person at their own pace and without recounting details.', array['Adults', 'Teens']::text[], '30 minutes in session', 'Many clients hold a confident prediction that telling anyone would be met with doubt. The sheet records the prediction and its certainty, the evidence the client uses for it, which is often one bad reaction, what a supportive reaction would look like, and whether there is a safe person they might tell only that something happened, no more. Complete it in session, never as homework, and let the client decide whether any step follows. Watch for a client who tests the prediction on the least safe person they know.', '[{"id": "f0", "type": "textarea", "label": "The prediction, in my own words: if I told someone, they would…"}, {"id": "f1", "type": "textarea", "label": "How sure I am, zero to one hundred, and where the certainty comes from:"}, {"id": "f2", "type": "textarea", "label": "The reactions I have actually had, if I have ever told anyone, and the reactions I have imagined:"}, {"id": "f3", "type": "textarea", "label": "What a believing response would look and sound like:"}, {"id": "f4", "type": "textarea", "label": "A safe person I could tell only that something happened, if and when I choose, and what I would say:"}, {"id": "f5", "type": "textarea", "label": "What I need in place before, during and after, if I decide to:"}]'::jsonb, array['sexual abuse', 'predictions', 'support', 'safety']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('not-owing-anyone-my-story-values-page', 'Not Owing Anyone My Story Values Page', 'act'::resource_kind, 'A values page for the client who feels obliged to explain their reactions or history, finding what they value about privacy and choice.', 'Use it to help a client reclaim the choice of who knows what, and act from that choice instead of from obligation.', array['Adults', 'Teens']::text[], '20 minutes', 'Survivors are often asked, or feel asked, to explain themselves: why they flinched, why they left early. The page has the client write the situations where they feel they owe an explanation, what they value about choosing their own audience, a short line for declining to explain, and what they would rather do with the energy. Nothing about the history is written. Watch for a client who swings to telling no one at all; the value is choice, and choice includes telling.', '[{"id": "f0", "type": "textarea", "label": "Situations where I feel I owe someone an explanation for how I am:"}, {"id": "f1", "type": "textarea", "label": "What I value about choosing who knows what about me:"}, {"id": "f2", "type": "textarea", "label": "A short line I can use when I choose not to explain:"}, {"id": "f3", "type": "textarea", "label": "Who I do choose to tell things to, and why they earned that:"}, {"id": "f4", "type": "textarea", "label": "One time this week I used the line, and what happened:"}, {"id": "f5", "type": "textarea", "label": "What I want to do with the energy I used to spend explaining:"}]'::jsonb, array['sexual abuse', 'values', 'boundaries', 'core ACT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('wise-mind-on-how-much-to-share-today-card', 'Wise Mind on How Much to Share Today Card', 'dbt'::resource_kind, 'A wise mind card for the start of a session or conversation, deciding how much to share today rather than too much or too little.', 'Use it to put the pace of disclosure in the client''s hands, in session and with people they trust.', array['Adults', 'Teens']::text[], 'Five minutes before a session or conversation', 'Emotion mind can pour everything out and leave the client raw; reasonable mind can seal it all and leave them alone. The card asks what each mind wants today, then what wise mind says about how much to share, with whom, and when to stop. It includes a signal for stopping. Nothing about the history itself is written on the card. Watch for a client who uses the card to say nothing every week; ask gently what wise mind would say about one sentence.', '[{"id": "f0", "type": "textarea", "label": "What emotion mind wants to do with this conversation today:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind wants to do:"}, {"id": "f2", "type": "textarea", "label": "After a slow breath: what wise mind says about how much to share, and with whom:"}, {"id": "f3", "type": "textarea", "label": "My signal for stopping, which I can use at any point:"}, {"id": "f4", "type": "textarea", "label": "How the conversation went, and how I felt an hour later:"}]'::jsonb, array['sexual abuse', 'wise mind', 'pacing', 'core DBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('safe-grown-ups-phone-book-craft', 'Safe Grown-Ups Phone Book Craft', 'kids'::resource_kind, 'A craft that makes a small booklet of safe grown-ups with their pictures and how to reach them, which the child keeps in their bag.', 'Use it to give a child a concrete list of people they can go to, made with a parent and kept within reach.', array['Children']::text[], '30 minutes', 'The child folds paper into a small booklet and gives one page to each safe grown-up they choose: a drawing or photo, the name, and how to find them, such as at school or by the phone in the kitchen. The parent helps spell and asks what makes each person feel safe. Add the 988 line as a page for emergencies with the parent explaining it. If the child discloses anything while making it, follow your reporting duties. Watch for a child who includes someone the parent has doubts about; the parent can gently ask what makes that person safe and decide privately what to do with the answer.', '[{"id": "f0", "type": "textarea", "label": "Draw the cover of your safe grown-ups phone book:"}, {"id": "f1", "type": "textarea", "label": "Who is on your pages, and what makes each of them a safe grown-up?"}, {"id": "f2", "type": "textarea", "label": "How do you find each one when you need them?"}, {"id": "f3", "type": "textarea", "label": "Where will you keep your book?"}, {"id": "f4", "type": "textarea", "label": "Which page would you turn to first if you had a worry, and what would you say?"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'craft']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('coping-skill-piggybacked-on-a-daily-habit-sheet', 'Coping Skill Piggybacked on a Daily Habit Sheet', 'worksheet'::resource_kind, 'A sheet that attaches one coping skill to a habit the client already has, so the practice happens without remembering to practice.', 'Use it to help a client who forgets to use skills until a crisis build one into something they already do every day.', array['Adults', 'Teens']::text[], '15 minutes to plan, two weeks to use', 'Skills practiced only in crisis never get good. The sheet lists the client''s automatic daily habits, from brushing teeth to waiting for the kettle, picks one, and attaches a thirty-second skill to it: a paced breath, a five-senses check, a thought noticed and named. The client logs whether the pairing fired each day. Watch for a client who picks a habit they do inconsistently; the anchor has to be one that happens without fail.', '[{"id": "f0", "type": "textarea", "label": "Habits I do every day without thinking, with the times they happen:"}, {"id": "f1", "type": "textarea", "label": "The one habit I will use as my anchor:"}, {"id": "f2", "type": "textarea", "label": "The thirty-second skill I will attach to it, exactly:"}, {"id": "f3", "type": "textarea", "label": "Days this week the pairing fired, and days it did not:"}, {"id": "f4", "type": "textarea", "label": "What was different on the days it did not fire:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: whether the skill shows up anywhere else on its own:"}]'::jsonb, array['coping skills', 'habits', 'routines', 'skills']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('needing-a-coping-skill-means-i-am-weak-belief-test-sheet', 'Needing a Coping Skill Means I Am Weak Belief Test Sheet', 'cbt'::resource_kind, 'A belief test for the client who sees using a skill as weakness, with a survey of who else uses skills and a test of using one openly.', 'Use it to loosen the belief that keeps a capable client from using what they already know.', array['Adults', 'Teens']::text[], '25 minutes', 'Some clients learn the skills and never use them because needing them would prove something. The sheet writes the belief out, lists the people the client admires and the routines they use to steady themselves, which are coping skills by another name, and plans one use of a skill in front of someone. It ends with a fairer belief. Watch for a client who grants exemptions to athletes and surgeons but not to themselves; ask what the difference is.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words: if I need a skill to cope, then I am…"}, {"id": "f1", "type": "textarea", "label": "People I admire, and what they do to steady themselves before and after hard things:"}, {"id": "f2", "type": "textarea", "label": "What I would think of a friend who used a breathing skill before a presentation:"}, {"id": "f3", "type": "textarea", "label": "My test: one skill I will use this week where someone can see, and my prediction:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, including what the other person did:"}, {"id": "f5", "type": "textarea", "label": "A fairer belief about what using a skill means:"}]'::jsonb, array['coping skills', 'core beliefs', 'behavioral experiment', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-as-tools-not-erasers-page', 'Coping Skills as Tools Not Erasers Page', 'act'::resource_kind, 'A page that sorts the client''s coping skills by whether they are used to live better or to erase a feeling, and resets the job of each.', 'Use it to help a client who is frustrated that skills do not remove feelings see what the skills are actually for.', array['Adults', 'Teens']::text[], '20 minutes', 'A client who uses a skill to make a feeling disappear will report that nothing works. The page lists each skill they use, what they have been asking it to do, and what it could do instead: make room, buy a minute, bring attention back to what matters. They rewrite the job description of each. Watch for a client who concludes that skills are pointless because they do not erase; the page is meant to lower the bar, not remove it.', '[{"id": "f0", "type": "textarea", "label": "The coping skills I use most, and what I have been asking each one to do:"}, {"id": "f1", "type": "textarea", "label": "Which of them I have been using as erasers, to make a feeling go away:"}, {"id": "f2", "type": "textarea", "label": "What happened to the feeling when the eraser did not work, and what I concluded about the skill:"}, {"id": "f3", "type": "textarea", "label": "A new job description for each skill: make room, buy a minute, turn me toward what matters:"}, {"id": "f4", "type": "textarea", "label": "One time this week I used a skill as a tool rather than an eraser:"}, {"id": "f5", "type": "textarea", "label": "What was different about the feeling and about what I did next:"}]'::jsonb, array['coping skills', 'willingness', 'core ACT', 'workability']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('skills-breakdown-point-early-warning-card', 'Skills Breakdown Point Early Warning Card', 'dbt'::resource_kind, 'A card that finds the emotion intensity at which the client''s skills stop working and lists the signs that they are approaching it.', 'Use it to help a client use skills before the point where no skill can reach them, instead of after.', array['Adults', 'Teens']::text[], '20 minutes to build, used daily', 'Every client has a point on the intensity scale past which thinking skills are gone and only the body remains. The card has them rate recent high moments, find the number where skills stopped working, and list the body and behavior signs at two points below it. Those signs are the cue for a skill, not the peak. Watch for a client who sets the warning signs too close to the peak; the card works when it fires early, and early feels unnecessary at first.', '[{"id": "f0", "type": "textarea", "label": "Three recent moments of high emotion, with the intensity of each, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "The number past which my skills stopped working in those moments:"}, {"id": "f2", "type": "textarea", "label": "What my body and behavior look like two points below that number:"}, {"id": "f3", "type": "textarea", "label": "The skill I will use when I see those signs, before the peak:"}, {"id": "f4", "type": "textarea", "label": "One time this week I caught the early signs and used the skill, and what happened:"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT', 'regulation']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('coping-skill-taboo-forbidden-words-game', 'Coping Skill Taboo Forbidden Words Game', 'game'::resource_kind, 'A group game where players describe a coping skill without using its obvious words, and the team guesses it against a timer.', 'Use it to make a group think about how a skill actually works, not just what it is called.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each card names a coping skill and three forbidden words, such as paced breathing with breath, slow and count forbidden. In teams, one player describes the skill without the forbidden words while their team guesses within a minute; the other team watches for forbidden words and buzzes. Rotate so everyone describes once. Debrief which skills were hardest to describe and what that says about how well they are understood. Watch for teams that memorize cards; shuffle in blank cards for the group to fill with their own skills.', '[{"id": "f0", "type": "textarea", "label": "Which skill did you have to describe, and which words were forbidden?"}, {"id": "f1", "type": "textarea", "label": "How did you explain it without those words?"}, {"id": "f2", "type": "textarea", "label": "Which skill was hardest for your team to guess, and why?"}, {"id": "f3", "type": "textarea", "label": "Did describing a skill without its name change how you think about it?"}, {"id": "f4", "type": "textarea", "label": "One skill you understand better now, and when you would use it:"}]'::jsonb, array['coping skills', 'group', 'game', 'skills']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('bird-flapping-near-me-step-plan-sheet', 'Bird Flapping Near Me Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a fear of birds, from photos to a park bench near pigeons to walking through a flock, with predictions for each step.', 'Use it to help a client who crosses streets to avoid pigeons approach birds in planned steps.', array['Adults', 'Teens']::text[], 'Several weeks', 'A fear of birds shapes routes, outdoor eating and whole seasons. The sheet builds steps from the client''s own list: a video with sound, a bench thirty feet from pigeons, ten feet, eating outside, walking through a flock that scatters. For each step they write the prediction, usually that a bird will fly at their face, and the result. Watch for a client who completes steps by stiffening and staring down; ask them to let their arms hang and notice the birds'' actual behavior.', '[{"id": "f0", "type": "textarea", "label": "The birds and situations I avoid, and what my days look like because of it:"}, {"id": "f1", "type": "textarea", "label": "My steps, from easiest to hardest, in my own order:"}, {"id": "f2", "type": "textarea", "label": "For this step: what I will do, my prediction, and how sure I am:"}, {"id": "f3", "type": "textarea", "label": "What the birds actually did, and what my body did:"}, {"id": "f4", "type": "textarea", "label": "How long the fear took to come down while I stayed:"}, {"id": "f5", "type": "textarea", "label": "The next step, and when I will take it:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('escalator-step-on-prediction-sheet', 'Escalator Step-On Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for a fear of escalators, with the feared outcome, the actual step-on, and a tally of rides across a week.', 'Use it to help a client who takes the stairs or the elevator to avoid escalators test what actually happens when they step on.', array['Adults', 'Teens']::text[], 'One week', 'Escalators combine height, motion and the moment of committing a foot. The sheet records the specific prediction for stepping on, such as losing balance or being stuck at the top, the certainty, and then the ride: where the client held, what the body did, how the exit went. A tally across a week shows what the predictions do with repetition. Watch for a client who rides only with a hand on a companion; make riding alone a step rather than a surprise.', '[{"id": "f0", "type": "textarea", "label": "My prediction for stepping on: exactly what will happen, and how sure I am:"}, {"id": "f1", "type": "textarea", "label": "The ride: where I held, how my body felt at the top and bottom, how the step-off went:"}, {"id": "f2", "type": "textarea", "label": "What actually happened compared with the prediction:"}, {"id": "f3", "type": "textarea", "label": "My rides this week, tallied, with the certainty rating for each before stepping on:"}, {"id": "f4", "type": "textarea", "label": "How the certainty changed across the rides:"}, {"id": "f5", "type": "textarea", "label": "The next version: a longer escalator, a crowded one, or riding without a companion:"}]'::jsonb, array['phobias', 'predictions', 'exposure', 'core CBT']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('weak-knees-at-the-scenic-overlook-willingness-page', 'Weak Knees at the Scenic Overlook Willingness Page', 'act'::resource_kind, 'A willingness page for a fear of heights that plans a visit to a lookout with the weak knees allowed to come along.', 'Use it to help a client who stays in the car at every overlook choose the view and make room for the body''s reaction.', array['Adults', 'Teens']::text[], '25 minutes to plan, one outing', 'The overlook is where the family stands and the client waits in the car. The page names what the client values about the view and the company, what the body does near a drop, a willingness rating for feeling it, and the plan: how far toward the rail, for how long, with the knees allowed to shake. Watch for a client who grips the rail and stares at the horizon the whole time; ask them to look down for a count of three and notice what the knees do.', '[{"id": "f0", "type": "textarea", "label": "The lookout or high place I have been avoiding, and who I have watched from the car:"}, {"id": "f1", "type": "textarea", "label": "What I value about being out there with them:"}, {"id": "f2", "type": "textarea", "label": "What my body does near a drop, described without judging it:"}, {"id": "f3", "type": "textarea", "label": "How willing I am, zero to ten, to let my body do that while I stand there:"}, {"id": "f4", "type": "textarea", "label": "My plan: how close, for how long, and what I will look at:"}, {"id": "f5", "type": "textarea", "label": "What happened, including what the knees did and what I saw:"}]'::jsonb, array['phobias', 'willingness', 'core ACT', 'exposure']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('participate-fully-at-the-petting-zoo-card', 'Participate Fully at the Petting Zoo Card', 'dbt'::resource_kind, 'A participate skill card for a visit to a petting zoo or farm, throwing the client into the activity instead of watching from the fence.', 'Use it to help a client with an animal fear practice the participate skill in a managed setting with gentle animals.', array['Adults', 'Teens', 'Children']::text[], 'One visit', 'Watching from the fence keeps the fear alive. The card plans a petting zoo visit where the client participates fully: feeding, brushing or holding, with attention on the animal''s fur and the activity rather than on the self. It names the step for the visit, what full participation would look like, and a check afterward of how much of the time was spent watching versus doing. For a child, the parent goes in too. Watch for a client who participates with the hands and stays in the head; ask what the fur felt like.', '[{"id": "f0", "type": "textarea", "label": "The animal and the activity I will participate in on this visit:"}, {"id": "f1", "type": "textarea", "label": "What full participation would look like for me, in plain actions:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the animal through my senses, not about myself:"}, {"id": "f3", "type": "textarea", "label": "Roughly how much of the time I spent doing versus watching:"}, {"id": "f4", "type": "textarea", "label": "What my fear did while I was fully in the activity:"}]'::jsonb, array['phobias', 'mindfulness', 'core DBT', 'exposure']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('plastic-bug-hide-and-seek-brave-game', 'Plastic Bug Hide and Seek Brave Game', 'game'::resource_kind, 'A game where plastic bugs are hidden around a room and players find them, pick them up and sort them, with a brave scale after each round.', 'Use it to turn an insect fear into a hunt with rules, turns and a rating that lets a child or group see fear change.', array['Children', 'Groups']::text[], '20 minutes', 'A set of plastic insects is hidden around the room while players close their eyes. On the signal, players hunt; a bug found must be carried in the hand, not in a cup, to the sorting table and placed in the right group by color or type. Each round, players rate their bravery before and after. Round two uses bigger or more realistic bugs. A parent plays too and carries bugs the same way. Debrief what changed across rounds. Watch for a player who refuses to touch a bug; let them point and have another player carry it, and count that as their round.', '[{"id": "f0", "type": "textarea", "label": "How many bugs did you find, and which one was the hardest to pick up?"}, {"id": "f1", "type": "textarea", "label": "What was your brave rating before the first round, and after the last one?"}, {"id": "f2", "type": "textarea", "label": "What did the bug feel like in your hand?"}, {"id": "f3", "type": "textarea", "label": "What did your grown-up or teammates do that helped?"}, {"id": "f4", "type": "textarea", "label": "What bug would you be willing to carry next time that you were not ready for today?"}]'::jsonb, array['phobias', 'game', 'children', 'exposure']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('camera-self-view-off-week-log', 'Camera Self-View Off Week Log', 'worksheet'::resource_kind, 'A week-long log of video calls with self-view turned off, recording what the client noticed when they could not watch themselves.', 'Use it to help a client who spends meetings monitoring their own face find out what the call is like without the mirror.', array['Adults', 'Teens']::text[], 'One week', 'Self-view turns every call into a mirror. For a week the client hides their own tile on every call and logs what they noticed about the conversation, the urge to turn it back on, and how tired they were after. Compare with a typical week. Watch for a client who replaces self-view with checking their reflection in the screen''s edge; name it as the same behavior. Keep the log about attention and the conversation, never about appearance.', '[{"id": "f0", "type": "textarea", "label": "Each call this week with self-view off: who it was with, and how long:"}, {"id": "f1", "type": "textarea", "label": "What I noticed about the conversation and the other people that I usually miss:"}, {"id": "f2", "type": "textarea", "label": "The urge to turn self-view back on: when it came, how strong, and what I did:"}, {"id": "f3", "type": "textarea", "label": "How tired I felt after calls this week compared with a normal week:"}, {"id": "f4", "type": "textarea", "label": "What I actually contributed to the calls, as far as I can tell:"}, {"id": "f5", "type": "textarea", "label": "Whether I will keep self-view off, and for which calls:"}]'::jsonb, array['body image', 'attention', 'self-monitoring', 'behavioral experiment']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('they-only-like-me-for-how-i-look-thought-check-sheet', 'They Only Like Me for How I Look Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the belief that the client''s relationships rest on appearance, with the evidence from how people actually treat them.', 'Use it to help a client test the idea that their worth to others is their looks, using what the people in their life actually do.', array['Adults', 'Teens']::text[], '20 minutes', 'The belief makes every relationship feel conditional. The sheet names the thought and the relationship it attaches to, then collects evidence: what the person asks about, what they come to the client for, how they behaved on days the client felt they looked their worst, and what the client values the person for in return. It ends with a fairer sentence. Watch for a client who dismisses every piece of evidence as politeness; ask what politeness would look like compared with real interest.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the person or people it attaches to:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, zero to one hundred:"}, {"id": "f2", "type": "textarea", "label": "What this person asks me about, comes to me for, and tells me about themselves:"}, {"id": "f3", "type": "textarea", "label": "How they treated me on days I felt I looked my worst:"}, {"id": "f4", "type": "textarea", "label": "What I value them for, and whether any of it is how they look:"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence about why this person is in my life:"}]'::jsonb, array['body image', 'thinking traps', 'core CBT', 'relationships']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('appearance-commentary-as-elevator-music-page', 'Appearance Commentary as Elevator Music Page', 'act'::resource_kind, 'A defusion page that recasts the mind''s running commentary on appearance as elevator music: always playing, rarely worth attention.', 'Use it to help a client let the appearance commentary play in the background while they get on with the day.', array['Adults', 'Teens']::text[], '15 minutes', 'The commentary is constant and the client treats each line as news. The page has them write a few typical lines, notice how repetitive they are, and practice hearing them as background music: present, not important, and no reason to stop what they are doing. It asks what they did while the music played. Watch for a client who tries to turn the music off, which is attention of a different kind; the practice is letting it play.', '[{"id": "f0", "type": "textarea", "label": "A few typical lines of my mind''s appearance commentary, as it says them:"}, {"id": "f1", "type": "textarea", "label": "How often these same lines repeat, and how long they have been on the playlist:"}, {"id": "f2", "type": "textarea", "label": "What I did this week while the music played, without stopping to listen:"}, {"id": "f3", "type": "textarea", "label": "What happened to the volume when I stopped treating each line as news:"}, {"id": "f4", "type": "textarea", "label": "One place where the music used to stop me, and what I did there this week:"}]'::jsonb, array['body image', 'defusion', 'core ACT', 'mindfulness']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('describe-not-judge-getting-dressed-card', 'Describe Not Judge Getting Dressed Card', 'dbt'::resource_kind, 'A describe skill card for getting dressed in the morning, naming fabric, color and fit in plain facts and setting every verdict aside.', 'Use it to turn the most judgment-heavy ten minutes of the day into a mindfulness practice.', array['Adults', 'Teens']::text[], 'Ten minutes each morning for a week', 'Getting dressed is where the judging mind runs loudest. The card asks the client to describe each item as they put it on in observable terms only: soft, blue, long-sleeved, warm. Every verdict about the body or the look is noticed and set aside like a thought in a stream. Nothing here mentions size or shape, and the card does not either. Watch for a client who describes the clothes and silently judges the mirror; add the step of describing what they see in the mirror as colors and shapes only.', '[{"id": "f0", "type": "textarea", "label": "The items I put on this morning, described in plain facts: fabric, color, length, warmth:"}, {"id": "f1", "type": "textarea", "label": "The verdicts that tried to get in, noticed and set aside:"}, {"id": "f2", "type": "textarea", "label": "How long getting dressed took compared with a normal morning:"}, {"id": "f3", "type": "textarea", "label": "What my mood was like leaving the house:"}, {"id": "f4", "type": "textarea", "label": "What I noticed across the week about the verdicts:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT', 'self-talk']::text[], '2026-11-17T15:00:00+00:00'::timestamptz),
  ('beach-day-comfort-plan-for-partners', 'Beach Day Comfort Plan for Partners', 'couples'::resource_kind, 'A plan for a couple''s beach or pool day where one partner dreads being seen, with what each will do and say so the day is about the water.', 'Use it to help a couple have a beach day both can enjoy, with the self-conscious partner''s needs planned and the other''s role clear.', array['Couples']::text[], '30 minutes', 'One partner loves the beach; the other has avoided it for years. The dreading partner writes what the day usually involves for them, what they would need to feel able to go, and what they want the other partner to do and not do. The other writes what they want from the day and what they are willing to adjust. Together they plan the spot, the cover-ups allowed without comment, and one thing they will do together in the water. Nothing about appearance is discussed on the day. Watch for the supportive partner offering reassurance about looks, which keeps looks at the center.', '[{"id": "f0", "type": "textarea", "label": "Partner who dreads it: what a beach day is like for me, and what I would need to go:"}, {"id": "f1", "type": "textarea", "label": "Partner who loves it: what I want from the day, and what I am willing to change:"}, {"id": "f2", "type": "textarea", "label": "What the dreading partner wants the other to do, and what to never say:"}, {"id": "f3", "type": "textarea", "label": "Our plan: the spot, the time, the cover-ups allowed without comment:"}, {"id": "f4", "type": "textarea", "label": "One thing we will do together in the water:"}, {"id": "f5", "type": "textarea", "label": "How the day went, and what we will keep for the next one:"}]'::jsonb, array['body image', 'couples', 'support', 'planning']::text[], '2026-11-17T15:00:00+00:00'::timestamptz)
